const plans = [
  { id:'SP-LEI-HR-TN-001', category:'Honeymoon & Romance', type:'Honeymoon Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Kodaikanal, Tamil Nadu','கொடைக்கானல், தமிழ்நாடு','कोडईकनाल, तमिलनाडु'), start:'Kodaikanal', end:'Kodaikanal', title:L('Kodaikanal Lakeside Honeymoon Escape','கொடைக்கானல் ஏரிக்கரை தேனிலவுப் பயணம்','कोडईकनाल झील किनारे हनीमून यात्रा'), overview:L('A quiet hill-country break for two, based in Kodaikanal. The plan pairs a gentle walk along Coaker’s Walk and time at Bryant Park with the broad rock formations at Pillar Rocks and a relaxed visit to the lakefront. Short local drives leave room for unhurried stops and a hotel rest.','கொடைக்கானலை மையமாகக் கொண்ட இருவருக்கான அமைதியான மலைப் பயணம். கோக்கர்ஸ் வாக் நடைபாதை மற்றும் பிரையன்ட் பூங்காவுடன், பில்லர் ராக்ஸின் பாறைத் தோற்றங்களையும் ஏரிக்கரை ஓய்வையும் இணைக்கிறது. குறுகிய உள்ளூர் வாகனப் பயணங்கள் நிதானமான இடைவேளைக்கும் ஹோட்டல் ஓய்வுக்கும் நேரம் தருகின்றன.','कोडईकनाल में ठहरकर दो लोगों के लिए शांत पहाड़ी अवकाश। योजना में कोकर वॉक और ब्रायंट पार्क की सैर के साथ पिलर रॉक्स की चट्टानें और झील किनारे आराम शामिल है। छोटी स्थानीय ड्राइव से बिना जल्दबाज़ी घूमने और होटल में विश्राम का समय मिलता है।'), best:L('October to June; clearest and coolest months are December to March.','அக்டோபர் முதல் ஜூன் வரை; டிசம்பர் முதல் மார்ச் வரை குளிர்ச்சியும் தெளிவும் அதிகம்.','अक्टूबर से जून; दिसंबर से मार्च अधिक ठंडा और साफ़ मौसम रहता है.'), weather:L('Typical peak-season daytime 12–20°C and nights 8–12°C; cool, mist can reduce visibility.','உச்ச பருவத்தில் பகலில் பொதுவாக 12–20°C, இரவில் 8–12°C; குளிரும் மூடுபனியும் இருக்கலாம்.','मुख्य मौसम में दिन आम तौर पर 12–20°C और रात 8–12°C; ठंड रहती है और कोहरा दृश्यता घटा सकता है.'), source:'https://www.tnurbantree.tn.gov.in/kodaikanal/about-city/', sourceName:'Kodaikanal Municipality', photo:'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=1200&q=85', photoCredit:'Representative mountain landscape · Unsplash', extra:L('Coaker’s Walk and Pillar Rocks are weather-sensitive viewpoints; check local access and visibility before setting out.','கோக்கர்ஸ் வாக் மற்றும் பில்லர் ராக்ஸ் வானிலையைச் சார்ந்த காட்சியிடங்கள்; புறப்படுவதற்கு முன் அணுகல் மற்றும் தெளிவைச் சரிபார்க்கவும்.','कोकर वॉक और पिलर रॉक्स मौसम पर निर्भर दृश्य स्थल हैं; निकलने से पहले पहुँच और दृश्यता जाँचें.'), stops:[
    [L('Coaker’s Walk','கோக்கர்ஸ் வாக்','कोकर वॉक'),L('A paved ridge path with open views across the plains on clear mornings.','தெளிவான காலையில் சமவெளியைப் பார்க்கக்கூடிய மலை விளிம்புப் நடைபாதை.','साफ़ सुबह में मैदानों का खुला दृश्य देने वाला पहाड़ी किनारे का पक्का पैदल मार्ग.')],
    [L('Bryant Park','பிரையன்ட் பூங்கா','ब्रायंट पार्क'),L('A landscaped public garden near the lake, known for its flower beds and greenhouse.','ஏரிக்கு அருகிலுள்ள மலர் பாத்திகள் மற்றும் கண்ணாடி மாளிகைக்குப் பெயர்பெற்ற பொதுப் பூங்கா.','झील के पास स्थित सार्वजनिक उद्यान, फूलों की क्यारियों और ग्रीनहाउस के लिए जाना जाता है.')],
    [L('Pillar Rocks viewpoint','பில்லர் ராக்ஸ் காட்சியிடம்','पिलर रॉक्स दृश्य स्थल'),L('A lookout over three tall granite pillars and the wooded valley below.','மூன்று உயரமான கிரானைட் பாறைகளையும் கீழுள்ள காடுகள் நிறைந்த பள்ளத்தாக்கையும் காணும் இடம்.','तीन ऊँचे ग्रेनाइट स्तंभों और नीचे की वनाच्छादित घाटी का दृश्य स्थल.')],
    [L('Kodaikanal Lake promenade','கொடைக்கானல் ஏரிக்கரை நடைபாதை','कोडईकनाल झील तट मार्ग'),L('A broad lakeside promenade for an easy walk; boating is a separate, ticketed activity.','எளிய நடைப்பயணத்திற்கான ஏரிக்கரைப் பாதை; படகு சவாரிக்கு தனி சீட்டு தேவை.','हल्की सैर के लिए झील किनारे का चौड़ा मार्ग; नौकायन अलग टिकट वाली गतिविधि है.')]
  ]},
  { id:'SP-LEI-HR-WI-001', category:'Honeymoon & Romance', type:'Honeymoon Tours', region:'West India', states:['Rajasthan'], destination:L('Udaipur, Rajasthan','உதய்பூர், ராஜஸ்தான்','उदयपुर, राजस्थान'), start:'Udaipur', end:'Udaipur', title:L('Udaipur Lakes & Gardens for Two','இருவருக்கான உதய்பூர் ஏரிகள் மற்றும் தோட்டங்கள்','दो लोगों के लिए उदयपुर की झीलें और बाग़'), overview:L('A relaxed lakeside escape built around Udaipur’s water and garden landscapes. A morning boat circuit on Lake Pichola is followed by the fountains and lawns of Saheliyon ki Bari. Day two brings a calm visit to Fateh Sagar’s promenade and the hilltop views from Sajjangarh before returning to town.','உதய்பூரின் ஏரிகள் மற்றும் தோட்டங்களை மையமாகக் கொண்ட நிதானமான பயணம். காலை பிச்சோலா ஏரிப் படகு சுற்றுப்பயணத்திற்குப் பிறகு சஹேலியோன் கி பாரியின் நீரூற்றுகள் மற்றும் பசுமைத் தோட்டங்களைப் பார்க்கலாம். இரண்டாம் நாள் ஃபதே சாகர் ஏரிக்கரை மற்றும் சஜ்ஜன்கரின் மலைமேல் காட்சிக்குப் பிறகு நகரத்திற்குத் திரும்பும்.','उदयपुर की झीलों और बगीचों पर केंद्रित आरामदायक यात्रा। सुबह पिछोला झील की नाव यात्रा के बाद सहेलियों की बाड़ी के फव्वारे और लॉन देखें। दूसरे दिन फतेह सागर तट और सज्जनगढ़ के पहाड़ी दृश्य के बाद शहर लौटें।'), best:L('September to March; October to February is especially comfortable.','செப்டம்பர் முதல் மார்ச் வரை; அக்டோபர் முதல் பிப்ரவரி வரை குறிப்பாக வசதியானது.','सितंबर से मार्च; अक्टूबर से फरवरी का मौसम विशेष रूप से सुहावना रहता है.'), weather:L('Typical peak-season daytime 18–29°C and nights 8–16°C; dry skies and cool evenings.','உச்ச பருவத்தில் பகலில் பொதுவாக 18–29°C, இரவில் 8–16°C; வறண்ட வானமும் குளிர்ந்த மாலைகளும்.','मुख्य मौसम में दिन आम तौर पर 18–29°C और रात 8–16°C; आसमान शुष्क और शामें ठंडी रहती हैं.'), source:'https://www.incredibleindia.gov.in/en/rajasthan/udaipur', sourceName:'Incredible India · Udaipur', photo:'https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Lake_Pichola_Udaipur.jpg/1280px-Lake_Pichola_Udaipur.jpg', photoCredit:'Lake Pichola · Wikimedia Commons', extra:L('Boat departures and Sajjangarh access depend on weather and operating hours; boat fare and monument entry are excluded unless quoted.','படகுப் புறப்பாடும் சஜ்ஜன்கர் அணுகலும் வானிலை மற்றும் செயல்பாட்டு நேரத்தைச் சார்ந்தவை; விலைப்பட்டியலில் சேர்க்கப்படாவிட்டால் படகுக் கட்டணம் மற்றும் நுழைவுக் கட்டணம் சேராது.','नाव के प्रस्थान और सज्जनगढ़ की पहुँच मौसम व समय पर निर्भर हैं; कोटेशन में शामिल न होने पर नाव और प्रवेश शुल्क अलग हैं.'), stops:[
    [L('Lake Pichola boat jetty','பிச்சோலா ஏரி படகுத் துறை','पिछोला झील नाव घाट'),L('A short boat circuit gives a water-level view of the old-city shoreline and surrounding hills.','குறுகிய படகுச் சுற்று பழைய நகரக் கரையையும் சுற்றியுள்ள மலைகளையும் ஏரியிலிருந்து காட்டுகிறது.','छोटी नाव यात्रा से पुराने शहर की झील किनारे की रेखा और आसपास की पहाड़ियाँ पानी के स्तर से दिखती हैं.')],
    [L('Saheliyon ki Bari','சஹேலியோன் கி பாரி','सहेलियों की बाड़ी'),L('A historic garden with fountains, pools and shaded paths, suited to a slow afternoon visit.','நீரூற்றுகள், குளங்கள் மற்றும் நிழல் நடைபாதைகள் கொண்ட வரலாற்றுத் தோட்டம்; நிதானமான பிற்பகல் வருகைக்கு ஏற்றது.','फव्वारों, तालों और छायादार रास्तों वाला ऐतिहासिक बगीचा; आराम से दोपहर घूमने के लिए उपयुक्त.')],
    [L('Fateh Sagar promenade','ஃபதே சாகர் ஏரிக்கரை நடைபாதை','फतेह सागर तट मार्ग'),L('A broad promenade beside the lake, with open water views and cafés nearby.','ஏரியோரம் திறந்த நீர்க்காட்சிகளும் அருகிலுள்ள சிற்றுண்டி இடங்களும் உள்ள நடைபாதை.','झील के पास चौड़ा मार्ग, खुला जल दृश्य और आसपास कैफ़े.')],
    [L('Sajjangarh Monsoon Palace viewpoint','சஜ்ஜன்கர் மான்சூன் அரண்மனை காட்சியிடம்','सज्जनगढ़ मॉनसून पैलेस दृश्य स्थल'),L('A hilltop overlook across Udaipur and its lakes; the uphill drive is planned in daylight.','உதய்பூரையும் அதன் ஏரிகளையும் காணும் மலைமேல் காட்சியிடம்; மலை ஏற்ற வாகனப் பயணம் பகலில் திட்டமிடப்படுகிறது.','उदयपुर और उसकी झीलों का पहाड़ी दृश्य स्थल; चढ़ाई वाली ड्राइव दिन के उजाले में रखी गई है.')]
  ]},
  { id:'SP-LEI-HR-IS-001', category:'Honeymoon & Romance', type:'Honeymoon Tours', region:'Islands', states:['Andaman and Nicobar Islands'], destination:L('Swaraj Dweep (Havelock), Andaman Islands','ஸ்வராஜ் தீவு (ஹேவ்லாக்), அந்தமான் தீவுகள்','स्वराज द्वीप (हैवलॉक), अंडमान द्वीपसमूह'), start:'Swaraj Dweep Jetty', end:'Swaraj Dweep Jetty', title:L('Swaraj Dweep Blue-Water Honeymoon','ஸ்வராஜ் தீவின் நீலக் கடல் தேனிலவு','स्वराज द्वीप का नीले समुद्र वाला हनीमून'), overview:L('A gentle island stay with one beach visit each morning and afternoon. The route focuses on Radhanagar and Kalapathar beaches on day one, then Elephant Beach and the Havelock waterfront on day two. Sea crossings, permits and water activities depend on weather and operator schedules.','ஒவ்வொரு நாளும் காலை மற்றும் பிற்பகலில் ஒரு கடற்கரை வருகையுடன் அமைந்த எளிய தீவுத் தங்கல். முதல் நாள் ராதாநகர் மற்றும் காலாபத்தர் கடற்கரைகள்; இரண்டாம் நாள் எலிபண்ட் கடற்கரை மற்றும் ஹேவ்லாக் நீர்முகம். கடல் பயணம், அனுமதி மற்றும் நீர்ச் செயல்பாடுகள் வானிலை மற்றும் இயக்குநர் அட்டவணையைச் சார்ந்தவை.','हर सुबह और दोपहर एक समुद्र तट देखने के साथ सरल द्वीप प्रवास। पहले दिन राधानगर और कालापाथर समुद्र तट; दूसरे दिन एलिफेंट बीच और हैवलॉक जलतट। समुद्री यात्रा, परमिट और जल गतिविधियाँ मौसम तथा संचालक के समय पर निर्भर हैं।'), best:L('November to April; avoid rough-sea monsoon periods for boat activities.','நவம்பர் முதல் ஏப்ரல் வரை; படகு செயல்பாடுகளுக்கு கடல் கொந்தளிக்கும் பருவமழைக் காலத்தைத் தவிர்க்கவும்.','नवंबर से अप्रैल; नाव गतिविधियों के लिए समुद्र अशांत रहने वाले मानसून समय से बचें.'), weather:L('Typical peak-season daytime 25–30°C; warm, humid and breezy, with brief showers possible.','உச்ச பருவத்தில் பகலில் பொதுவாக 25–30°C; வெப்பம், ஈரப்பதம் மற்றும் கடற்காற்று; குறுகிய மழை சாத்தியம்.','मुख्य मौसम में दिन आम तौर पर 25–30°C; गर्म, नम और समुद्री हवा वाला मौसम, कभी-कभी हल्की बारिश.'), source:'https://www.incredibleindia.gov.in/en/andaman-and-nicobar-islands', sourceName:'Incredible India · Andaman and Nicobar Islands', photo:'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85', photoCredit:'Representative tropical beach image · Unsplash', extra:L('Inter-island ferries and beach access may be suspended in rough seas. Water sports are optional and payable directly unless added to the final quotation.','கடல் கொந்தளித்தால் தீவுகளுக்கிடையிலான படகுகளும் கடற்கரை அணுகலும் நிறுத்தப்படலாம். நீர்விளையாட்டுகள் விருப்பத் தேர்வு; இறுதி விலைப்பட்டியலில் சேர்க்காவிட்டால் நேரடியாகக் கட்டணம் செலுத்த வேண்டும்.','समुद्र खराब होने पर द्वीपों के बीच फेरी और समुद्र तट की पहुँच रुक सकती है। जल क्रीड़ाएँ वैकल्पिक हैं और अंतिम कोटेशन में जोड़े बिना उनका भुगतान अलग करना होगा.'), stops:[
    [L('Radhanagar Beach','ராதாநகர் கடற்கரை','राधानगर बीच'),L('A long sandy west-coast beach for a daylight walk and sunset viewing from permitted areas.','பகல் நடைப்பயணத்திற்கும் அனுமதிக்கப்பட்ட பகுதியில் சூரிய அஸ்தமனம் காணவும் ஏற்ற நீண்ட மணற்கரை.','दिन में टहलने और अनुमत क्षेत्र से सूर्यास्त देखने के लिए लंबा रेतीला पश्चिमी तट.')],
    [L('Kalapathar Beach','காலாபத்தர் கடற்கரை','कालापाथर बीच'),L('A quiet eastern-shore stop known for dark rocks, pale sand and early-morning light.','கருமையான பாறைகள், வெளிர் மணல் மற்றும் காலை ஒளிக்குப் பெயர்பெற்ற அமைதியான கிழக்குக் கரை.','गहरे पत्थरों, हल्की रेत और सुबह की रोशनी के लिए जाना जाने वाला शांत पूर्वी तट.')],
    [L('Elephant Beach landing area','எலிபண்ட் கடற்கரை இறங்குமிடம்','एलिफेंट बीच उतरने का स्थान'),L('A boat-access beach used for supervised snorkelling and reef activities when conditions allow.','சூழ்நிலை அனுமதிக்கும்போது கண்காணிப்புடன் ஸ்னோர்கலிங் மற்றும் பவளப்பாறை செயல்பாடுகளுக்குப் பயன்படுத்தப்படும் படகு வழிக் கடற்கரை.','मौसम अनुमति दे तो निगरानी में स्नॉर्कलिंग और रीफ़ गतिविधियों वाला नाव से पहुँचा जाने वाला तट.')],
    [L('Havelock waterfront and market','ஹேவ்லாக் நீர்முகம் மற்றும் சந்தை','हैवलॉक जलतट और बाज़ार'),L('A relaxed local walk near the jetty for island supplies and a view of the harbour.','துறைமுகக் காட்சியுடன் தீவுத் தேவைகளைப் பெறுவதற்கான துறைமுக அருகிலான உள்ளூர் நடைப்பயணம்.','जेट्टी के पास द्वीप की ज़रूरतों और बंदरगाह के दृश्य के लिए आरामदायक स्थानीय सैर.')]
  ]},

  { id:'SP-LEI-FAM-SI-001', category:'Family Holidays', type:'Family Tours', region:'South India', states:['Karnataka'], destination:L('Coorg (Kodagu), Karnataka','கூர்க் (கொடகு), கர்நாடகா','कूर्ग (कोडगु), कर्नाटक'), start:'Madikeri', end:'Madikeri', title:L('Coorg Easy-Paced Family Nature Break','கூர்க் குடும்பத்திற்கான நிதானமான இயற்கைப் பயணம்','कूर्ग का परिवार-अनुकूल प्रकृति अवकाश'), overview:L('A family-friendly Kodagu break with short drives and open-air stops. Visit Abbey Falls and Raja’s Seat on day one, then explore the Cauvery Nisargadhama nature park and a permitted coffee-estate walking trail on day two. The sequence keeps active walking earlier in the day and leaves a rest window at the hotel.','குறுகிய வாகனப் பயணங்களும் திறந்தவெளி இடங்களும் கொண்ட குடும்பப் பயணம். முதல் நாள் அப்பே நீர்வீழ்ச்சி மற்றும் ராஜாஸ் சீட்; இரண்டாம் நாள் காவிரி நிசர்கதாமா இயற்கைப் பூங்கா மற்றும் அனுமதிக்கப்பட்ட காபித் தோட்ட நடைபாதை. அதிக நடைபயணம் காலை நேரத்தில் அமைக்கப்பட்டு, ஹோட்டல் ஓய்வுக்கான நேரமும் விடப்பட்டுள்ளது.','छोटी ड्राइव और खुले प्राकृतिक स्थलों वाली परिवार-अनुकूल कोडगु यात्रा। पहले दिन एबी फॉल्स और राजा सीट; दूसरे दिन कावेरी निसर्गधाम प्रकृति पार्क और अनुमति प्राप्त कॉफ़ी बागान में पैदल भ्रमण। चलने वाले हिस्से सुबह रखे गए हैं और होटल में आराम का समय भी है।'), best:L('October to March; November to February is usually coolest and driest.','அக்டோபர் முதல் மார்ச் வரை; நவம்பர் முதல் பிப்ரவரி வரை பொதுவாக குளிர்ச்சியும் வறட்சியும் அதிகம்.','अक्टूबर से मार्च; नवंबर से फरवरी आम तौर पर सबसे ठंडा और सूखा समय है.'), weather:L('Typical peak-season daytime 18–28°C and nights 12–18°C; mild with cool mornings.','உச்ச பருவத்தில் பகலில் பொதுவாக 18–28°C, இரவில் 12–18°C; மிதமான வானிலை, குளிர்ந்த காலை.','मुख्य मौसम में दिन आम तौर पर 18–28°C और रात 12–18°C; सुहावना मौसम और ठंडी सुबहें.'), source:'https://www.incredibleindia.gov.in/en/karnataka/coorg', sourceName:'Incredible India · Coorg', photo:'https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Robusta_Coffee_Field_Mixed_Shade_Trees_Coorg_Apr24_A7C_10436.jpg/1280px-Robusta_Coffee_Field_Mixed_Shade_Trees_Coorg_Apr24_A7C_10436.jpg', photoCredit:'TA Gonsalves · CC BY-SA 4.0 · Wikimedia Commons', extra:L('Abbey Falls can be slippery after rain; use the marked viewing area. Estate walks require the owner’s permission and are not assumed to be included.','மழைக்குப் பிறகு அப்பே நீர்வீழ்ச்சி வழுக்கலாக இருக்கலாம்; குறிக்கப்பட்ட பார்வைப் பகுதியைப் பயன்படுத்தவும். தோட்ட நடைபயணத்திற்கு உரிமையாளரின் அனுமதி தேவை; அது சேர்க்கப்பட்டதாக கருதப்படாது.','बारिश के बाद एबी फॉल्स के पास फिसलन हो सकती है; चिह्नित दृश्य क्षेत्र का उपयोग करें। बागान भ्रमण के लिए मालिक की अनुमति चाहिए और इसे शामिल न मानें.'), stops:[
    [L('Abbey Falls viewpoint','அப்பே நீர்வீழ்ச்சி பார்வையிடம்','एबी फॉल्स दृश्य स्थल'),L('A forest-edged waterfall reached by a marked footpath and steps from the parking area.','வாகன நிறுத்தத்திலிருந்து குறிக்கப்பட்ட நடைபாதை மற்றும் படிகள் வழியாகச் செல்லும் காடோர நீர்வீழ்ச்சி.','पार्किंग से चिह्नित पैदल मार्ग और सीढ़ियों द्वारा पहुँचा जाने वाला वन किनारे का झरना.')],
    [L('Raja’s Seat garden','ராஜாஸ் சீட் தோட்டம்','राजा सीट उद्यान'),L('A maintained garden lookout over the Madikeri valley, best in clear late-afternoon light.','மடிகேரி பள்ளத்தாக்கைக் காணும் பராமரிக்கப்பட்ட தோட்டக் காட்சியிடம்; தெளிவான பிற்பகல் சிறந்தது.','मडिकेरी घाटी का सुव्यवस्थित बगीचा दृश्य स्थल; साफ़ दिन की देर दोपहर बेहतर रहती है.')],
    [L('Cauvery Nisargadhama nature park','காவிரி நிசர்கதாமா இயற்கைப் பூங்கா','कावेरी निसर्गधाम प्रकृति पार्क'),L('A river-island park with shaded walking paths and designated visitor areas.','நிழலான நடைபாதைகள் மற்றும் பார்வையாளர் பகுதிகளைக் கொண்ட ஆற்றுத் தீவுப் பூங்கா.','छायादार पगडंडियों और निर्धारित आगंतुक क्षेत्रों वाला नदी-द्वीप पार्क.')],
    [L('Madikeri coffee-estate trail','மடிகேரி காபித் தோட்ட நடைபாதை','मडिकेरी कॉफ़ी बागान पगडंडी'),L('A guided, permission-based walk introduces shade-grown coffee plants and estate work.','நிழலில் வளரும் காபிச் செடிகள் மற்றும் தோட்டப் பணிகளை அறிமுகப்படுத்தும் அனுமதி அடிப்படையிலான வழிகாட்டியுடன் நடைபயணம்.','छाया में उगाई जाने वाली कॉफ़ी और बागान के काम से परिचित कराने वाला अनुमति-आधारित गाइडेड वॉक.')]
  ]},
  { id:'SP-LEI-FAM-NI-001', category:'Family Holidays', type:'Family Tours', region:'North India', states:['Rajasthan'], destination:L('Jaipur, Rajasthan','ஜெய்ப்பூர், ராஜஸ்தான்','जयपुर, राजस्थान'), start:'Jaipur', end:'Jaipur', title:L('Jaipur Family City & Garden Holiday','ஜெய்ப்பூர் குடும்ப நகரம் மற்றும் தோட்டப் பயணம்','जयपुर परिवार शहर और बाग़ यात्रा'), overview:L('A compact city stay with accessible attractions and a comfortable pace for families. Day one combines the open lawns and play spaces at Jawahar Circle with a daylight visit to the Amber area lookout. Day two pairs the Central Park loop with the gardens and lake views at Kanak Vrindavan. Timed entry and access are checked for the travel date.','குடும்பங்களுக்கு ஏற்ற அணுகலுடனும் வசதியான வேகத்துடனும் அமைந்த நகரப் பயணம். முதல் நாள் ஜவஹர் சர்க்கிளின் திறந்த பசுமை மற்றும் விளையாட்டு இடங்களுடன் ஆம்பர் பகுதி காட்சியிடத்திற்கு பகல் வருகை. இரண்டாம் நாள் சென்ட்ரல் பார்க் நடைபாதையையும் கனக் பிரிந்தாவன் தோட்டம் மற்றும் ஏரிக்காட்சியையும் இணைக்கிறது. பயணத் தேதிக்கான நுழைவு நேரம் மற்றும் அணுகல் சரிபார்க்கப்படும்.','परिवारों के लिए सुलभ स्थलों और आरामदायक गति वाली छोटी शहर यात्रा। पहले दिन जवाहर सर्कल के खुले लॉन और खेल क्षेत्र के साथ आमेर क्षेत्र के दृश्य स्थल की दिन में सैर। दूसरे दिन सेंट्रल पार्क का चक्कर और कनक वृंदावन के बगीचे व झील दृश्य। यात्रा की तारीख के प्रवेश समय और पहुँच की जाँच होगी।'), best:L('October to March; November to February is most comfortable for outdoor visits.','அக்டோபர் முதல் மார்ச் வரை; வெளிப்புற வருகைக்கு நவம்பர் முதல் பிப்ரவரி வரை வசதியானது.','अक्टूबर से मार्च; खुले में घूमने के लिए नवंबर से फरवरी सबसे आरामदायक है.'), weather:L('Typical peak-season daytime 20–29°C and nights 8–16°C; dry, sunny days and cooler evenings.','உச்ச பருவத்தில் பகலில் பொதுவாக 20–29°C, இரவில் 8–16°C; வெயிலும் வறட்சியும், குளிர்ந்த மாலைகளும்.','मुख्य मौसम में दिन आम तौर पर 20–29°C और रात 8–16°C; धूप और शुष्क मौसम, शामें ठंडी.'), source:'https://www.incredibleindia.gov.in/en/rajasthan/jaipur', sourceName:'Incredible India · Jaipur', photo:'https://images.unsplash.com/photo-1599661046827-dacff0c0f09a?w=1200&q=85', photoCredit:'Representative Jaipur city image · Unsplash', extra:L('Amber-area viewpoints involve steps and uneven surfaces. Any monument entry ticket is separate unless included in the final quotation.','ஆம்பர் பகுதி காட்சியிடங்களில் படிகளும் சமமற்ற தரையும் இருக்கலாம். இறுதி விலைப்பட்டியலில் சேர்க்கப்படாவிட்டால் நினைவுச் சின்ன நுழைவுச் சீட்டு தனியாகும்.','आमेर क्षेत्र के दृश्य स्थलों पर सीढ़ियाँ और असमतल रास्ते हैं। अंतिम कोटेशन में शामिल न होने पर स्मारक प्रवेश टिकट अलग होगा.'), stops:[
    [L('Jawahar Circle Garden','ஜவஹர் சர்க்கிள் தோட்டம்','जवाहर सर्कल उद्यान'),L('A large landscaped roundabout park with walking paths, lawns and a family play area.','நடைபாதைகள், பசுமைத் தரை மற்றும் குடும்ப விளையாட்டு இடம் கொண்ட பெரிய தோட்டப் பூங்கா.','पैदल मार्ग, लॉन और परिवार के खेल क्षेत्र वाला बड़ा सुसज्जित उद्यान.')],
    [L('Amber area hill lookout','ஆம்பர் பகுதி மலைக் காட்சியிடம்','आमेर क्षेत्र पहाड़ी दृश्य स्थल'),L('A daylight stop for views across the hills and lake basin; access depends on local rules.','மலைகள் மற்றும் ஏரிப் பள்ளத்தாக்கைக் காணும் பகல் நேர நிறுத்தம்; உள்ளூர் விதிகளுக்கு அணுகல் உட்பட்டது.','पहाड़ियों और झील बेसिन के दृश्य के लिए दिन का पड़ाव; पहुँच स्थानीय नियमों के अधीन है.')],
    [L('Jaipur Central Park','ஜெய்ப்பூர் சென்ட்ரல் பார்க்','जयपुर सेंट्रल पार्क'),L('A broad city park with a long walking loop, open lawns and space to rest.','நீண்ட நடைவட்டம், திறந்த பசுமை மற்றும் ஓய்விடம் கொண்ட நகரப் பூங்கா.','लंबे पैदल चक्कर, खुले लॉन और आराम की जगह वाला बड़ा शहर पार्क.')],
    [L('Kanak Vrindavan gardens','கனக் பிரிந்தாவன் தோட்டங்கள்','कनक वृंदावन उद्यान'),L('A landscaped garden setting below the hills, with lawns and views toward the valley.','மலைகளின் அடிவாரத்தில் பசுமைத் தரையும் பள்ளத்தாக்குக் காட்சியும் கொண்ட தோட்டம்.','पहाड़ियों के नीचे लॉन और घाटी की ओर दृश्य वाला सुसज्जित उद्यान.')]
  ]},
  { id:'SP-LEI-FAM-SI-002', category:'Family Holidays', type:'Family Tours', region:'South India', states:['Kerala'], destination:L('Alappuzha, Kerala','ஆலப்புழா, கேரளா','अलप्पुझा, केरल'), start:'Alappuzha', end:'Alappuzha', title:L('Alappuzha Backwater Family Stay','ஆலப்புழா உப்பங்கழி குடும்பப் பயணம்','अलप्पुझा बैकवॉटर पारिवारिक प्रवास'), overview:L('An easy-paced two-day stay beside Kerala’s backwaters. The first day visits the Alappuzha lighthouse area and the beach promenade; day two follows a short, locally operated backwater boat circuit and a quiet walk along the canal-front. Boat service is optional and depends on weather, operator hours and ticket availability.','கேரள உப்பங்கழிக்கு அருகில் அமைந்த நிதானமான இரண்டு நாள் பயணம். முதல் நாள் ஆலப்புழா கலங்கரை விளக்குப் பகுதி மற்றும் கடற்கரை நடைபாதை; இரண்டாம் நாள் உள்ளூர் இயக்குநரின் குறுகிய உப்பங்கழிப் படகு சுற்று மற்றும் கால்வாய் கரை நடை. படகு சேவை விருப்பத் தேர்வு; வானிலை, இயக்குநர் நேரம் மற்றும் சீட்டு கிடைப்பைச் சார்ந்தது.','केरल के बैकवॉटर के पास आरामदायक दो-दिवसीय प्रवास। पहले दिन अलप्पुझा लाइटहाउस क्षेत्र और समुद्र तट मार्ग; दूसरे दिन स्थानीय संचालक की छोटी बैकवॉटर नाव यात्रा और नहर किनारे सैर। नाव यात्रा वैकल्पिक है और मौसम, संचालक समय तथा टिकट उपलब्धता पर निर्भर है.'), best:L('October to February; November to January is generally cooler and less humid.','அக்டோபர் முதல் பிப்ரவரி வரை; நவம்பர் முதல் ஜனவரி வரை பொதுவாக குளிர்ச்சியும் குறைந்த ஈரப்பதமும்.','अक्टूबर से फरवरी; नवंबर से जनवरी आम तौर पर ठंडा और कम उमस वाला समय है.'), weather:L('Typical peak-season daytime 24–31°C and nights 22–25°C; warm, humid coastal weather.','உச்ச பருவத்தில் பகலில் பொதுவாக 24–31°C, இரவில் 22–25°C; வெப்பமான ஈரமான கடலோர வானிலை.','मुख्य मौसम में दिन आम तौर पर 24–31°C और रात 22–25°C; गर्म और नम तटीय मौसम.'), source:'https://www.incredibleindia.gov.in/en/kerala/alappuzha', sourceName:'Incredible India · Alappuzha', photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Alappuzha_Beach.jpg/1280px-Alappuzha_Beach.jpg', photoCredit:'Alappuzha Beach · Wikimedia Commons', extra:L('Houseboat or shikara costs and meals on board are not included. Choose an operator with life jackets and confirm the return jetty and trip duration before boarding.','ஹவுஸ்போட் அல்லது ஷிகாரா கட்டணம் மற்றும் படகிலான உணவு சேர்க்கப்படவில்லை. உயிர்காப்பு ஜாக்கெட் வழங்கும் இயக்குநரைத் தேர்ந்தெடுத்து ஏறும் முன் திரும்பும் துறைமுகம் மற்றும் பயண நேரத்தை உறுதிப்படுத்தவும்.','हाउसबोट या शिकारा का खर्च और नाव पर भोजन शामिल नहीं है। लाइफ़ जैकेट देने वाला संचालक चुनें और सवार होने से पहले वापसी घाट व यात्रा अवधि पक्की करें.'), stops:[
    [L('Alappuzha Lighthouse precinct','ஆலப்புழா கலங்கரை விளக்குப் பகுதி','अलप्पुझा लाइटहाउस परिसर'),L('A coastal landmark and nearby shoreline walk; tower access follows the posted schedule.','கடலோர அடையாளமும் அருகிலுள்ள கரை நடைபாதையும்; கோபுர நுழைவு அறிவிக்கப்பட்ட நேரத்தைப் பின்பற்றும்.','तटीय पहचान स्थल और पास का किनारा मार्ग; टावर प्रवेश घोषित समय के अनुसार है.')],
    [L('Alappuzha Beach promenade','ஆலப்புழா கடற்கரை நடைபாதை','अलप्पुझा बीच मार्ग'),L('A broad public shoreline for a relaxed walk; swimming is not part of the plan.','நிதானமான நடைப்பயணத்திற்கான பொதுக் கடற்கரை; நீச்சல் திட்டத்தில் இல்லை.','आराम से टहलने के लिए सार्वजनिक तट; तैराकी इस योजना में शामिल नहीं है.')],
    [L('Pallathuruthy backwater boat route','பள்ளத்துருத்தி உப்பங்கழிப் படகு வழி','पल्लातुरुथी बैकवॉटर नाव मार्ग'),L('A short boat circuit through canals and village waterways with views of daily backwater life.','கால்வாய்கள் மற்றும் கிராம நீர்வழிகள் வழியாகச் செல்லும் குறுகிய படகுப் பயணம்; உப்பங்கழி வாழ்வைக் காணலாம்.','नहरों और गाँव के जलमार्गों से छोटी नाव यात्रा, जिसमें बैकवॉटर का दैनिक जीवन दिखता है.')],
    [L('Alappuzha canal-front walk','ஆலப்புழா கால்வாய் கரை நடை','अलप्पुझा नहर किनारे सैर'),L('A low-intensity walk beside the town canals, planned outside the hottest midday period.','நகரக் கால்வாயோரம் அமைந்த எளிய நடை; அதிக வெப்பமுள்ள நண்பகலைத் தவிர்த்து திட்டமிடப்படும்.','नगर की नहर के पास हल्की सैर, दिन की सबसे गर्म दोपहर से बाहर रखी गई है.')]
  ]},

  { id:'SP-LEI-WILD-TN-001', category:'Wildlife & Nature', type:'Wildlife & Nature Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Mudumalai Tiger Reserve, Tamil Nadu','முதுமலை புலிகள் காப்பகம், தமிழ்நாடு','मुदुमलाई टाइगर रिज़र्व, तमिलनाडु'), start:'Theppakadu', end:'Theppakadu', title:L('Mudumalai Guided Safari & Forest Edge','முதுமலை வழிகாட்டியுடன் சஃபாரி மற்றும் வனப்பகுதி','मुदुमलाई गाइडेड सफ़ारी और वन किनारा'), overview:L('A wildlife-focused stay at the Tamil Nadu edge of the Nilgiri landscape. The plan uses an official reserve safari slot and a separate forest-edge nature walk, with long rest periods between activities. Wildlife sightings are never guaranteed; visitors follow reserve rules and remain in the authorized vehicle or marked area.','நீலகிரி நிலப்பரப்பின் தமிழ்நாடு பகுதியில் அமைந்த வனவிலங்கு பயணம். அதிகாரப்பூர்வ காப்பக சஃபாரி நேரத்தையும் தனி வன எல்லை இயற்கை நடைப்பயணத்தையும், இடையில் போதிய ஓய்வுடன் திட்டமிடுகிறது. விலங்குகளைப் பார்ப்பது உறுதி அல்ல; காப்பக விதிகளைப் பின்பற்றி அனுமதிக்கப்பட்ட வாகனம் அல்லது குறிக்கப்பட்ட பகுதியில் இருக்க வேண்டும்.','नीलगिरि परिदृश्य के तमिलनाडु हिस्से में वन्यजीव केंद्रित प्रवास। योजना में रिज़र्व की आधिकारिक सफ़ारी स्लॉट और अलग वन किनारा प्रकृति सैर है, गतिविधियों के बीच पर्याप्त विश्राम के साथ। वन्यजीव दिखना तय नहीं है; रिज़र्व नियम मानें और अधिकृत वाहन या चिह्नित क्षेत्र में रहें।'), best:L('November to February; avoid the hottest March–April afternoons.','நவம்பர் முதல் பிப்ரவரி வரை; மார்ச்–ஏப்ரல் கடும் பிற்பகல் வெப்பத்தைத் தவிர்க்கவும்.','नवंबर से फरवरी; मार्च–अप्रैल की सबसे गर्म दोपहर से बचें.'), weather:L('Typical peak-season daytime 18–27°C and nights 10–16°C; dry mornings, warmer afternoons.','உச்ச பருவத்தில் பகலில் பொதுவாக 18–27°C, இரவில் 10–16°C; வறண்ட காலை, வெப்பமான பிற்பகல்.','मुख्य मौसम में दिन आम तौर पर 18–27°C और रात 10–16°C; सुबह सूखी और दोपहर गर्म.'), source:'https://www.mudumalaitigerreserve.com/PlanYourVisit/Programme?category=6461f503362e04365be5c3a1&name=Jungle+Safari+Gypsy&type=6467282e541e546f5567d8f2', sourceName:'Mudumalai Tiger Reserve · Visitor programme', photo:'https://www.mudumalainationalpark.in/images/mtr.jpg', photoCredit:'Mudumalai forest wildlife · Mudumalai National Park', extra:L('The reserve lists safari departures from 06:30, with the last departure at 17:00; exact slots and tickets must be confirmed with the reserve. No private vehicle is permitted in the core safari area.','காப்பகத் தகவலில் 06:30 முதல் சஃபாரி புறப்பாடுகளும் கடைசி புறப்பாடு 17:00 மணிக்கும் குறிப்பிடப்பட்டுள்ளன; சரியான நேரம் மற்றும் சீட்டை காப்பகத்துடன் உறுதிப்படுத்தவும். மைய சஃபாரி பகுதியில் தனியார் வாகனம் அனுமதிக்கப்படாது.','रिज़र्व की जानकारी में सफ़ारी प्रस्थान 06:30 से और अंतिम प्रस्थान 17:00 बजे है; सही स्लॉट और टिकट रिज़र्व से पक्के करें। मुख्य सफ़ारी क्षेत्र में निजी वाहन अनुमत नहीं है.'), stops:[
    [L('Theppakadu safari boarding point','தெப்பக்காடு சஃபாரி ஏறும் இடம்','थेप्पकाडु सफ़ारी बोर्डिंग स्थल'),L('Official reserve-operated safari departures use timed tickets and authorized vehicles.','காப்பகத்தால் இயக்கப்படும் அதிகாரப்பூர்வ சஃபாரி நேரச்சீட்டு மற்றும் அனுமதிக்கப்பட்ட வாகனங்களைப் பயன்படுத்துகிறது.','रिज़र्व की आधिकारिक सफ़ारी में समयबद्ध टिकट और अधिकृत वाहन उपयोग होते हैं.')],
    [L('Mudumalai forest interpretation stop','முதுமலை வன விளக்க மையம்','मुदुमलाई वन व्याख्या स्थल'),L('A visitor orientation stop for the reserve’s habitats, safety rules and conservation work.','காப்பக வாழிடங்கள், பாதுகாப்பு விதிகள் மற்றும் பாதுகாப்புப் பணிகள் குறித்த பார்வையாளர் அறிமுக இடம்.','रिज़र्व के आवास, सुरक्षा नियम और संरक्षण कार्य की जानकारी देने वाला आगंतुक परिचय स्थल.')],
    [L('Masinagudi forest-edge drive','மசினகுடி வன எல்லைச் சாலை','मसिनागुडी वन किनारा मार्ग'),L('A daylight public-road drive along the forest edge; wildlife is viewed only from a safe, permitted distance.','வன எல்லை வழியாகப் பொதுச் சாலையில் பகல் பயணம்; விலங்குகளை பாதுகாப்பான அனுமதிக்கப்பட்ட தூரத்திலிருந்து மட்டுமே பார்க்கவும்.','वन किनारे की सार्वजनिक सड़क पर दिन की ड्राइव; वन्यजीव केवल सुरक्षित और अनुमत दूरी से देखें.')],
    [L('Nilgiri foothill birding walk','நீலகிரி அடிவாரப் பறவைக் கண்காணிப்பு நடை','नीलगिरि तलहटी पक्षी अवलोकन सैर'),L('A quiet guided walk on an approved path to observe common woodland birds and plants.','பொதுவான வனப் பறவைகள் மற்றும் தாவரங்களைப் பார்க்க அங்கீகரிக்கப்பட்ட பாதையில் அமைதியான வழிகாட்டி நடை.','सामान्य वन पक्षियों और पौधों को देखने के लिए स्वीकृत पथ पर शांत गाइडेड वॉक.')]
  ]},
  { id:'SP-LEI-WILD-NE-001', category:'Wildlife & Nature', type:'Wildlife & Nature Tours', region:'Northeast India', states:['Assam'], destination:L('Kaziranga National Park, Assam','காசிரங்கா தேசியப் பூங்கா, அசாம்','काज़ीरंगा राष्ट्रीय उद्यान, असम'), start:'Kohora', end:'Kohora', title:L('Kaziranga Rhino Country Nature Stay','காசிரங்கா காண்டாமிருக இயற்கைத் தங்கல்','काज़ीरंगा गैंडा क्षेत्र प्रकृति प्रवास'), overview:L('A short nature break based near Kohora, Assam. One scheduled jeep safari is placed in the cooler morning window, with an interpretation visit and a second reserve zone drive on the following day. Park zones, safari permits and seasonal opening dates are set by the authorities; animal sightings are not guaranteed.','அசாமின் கோஹோராவை மையமாகக் கொண்ட குறுகிய இயற்கைப் பயணம். குளிர்ந்த காலை நேரத்தில் ஒரு ஜீப் சஃபாரியும், விளக்க மைய வருகையும் மறுநாள் காப்பகத்தின் மற்றொரு பகுதி பயணமும் உள்ளன. பூங்கா பகுதிகள், சஃபாரி அனுமதி மற்றும் பருவத் திறப்பு அதிகாரிகளால் நிர்ணயிக்கப்படும்; விலங்குகள் காணப்படுவது உறுதி அல்ல.','असम के कोहोरा के पास ठहरकर छोटी प्रकृति यात्रा। ठंडी सुबह में एक जीप सफ़ारी, व्याख्या केंद्र की सैर और अगले दिन रिज़र्व के दूसरे क्षेत्र में ड्राइव है। पार्क ज़ोन, सफ़ारी परमिट और मौसमी खुलने की तारीखें अधिकारी तय करते हैं; जानवर दिखना निश्चित नहीं है।'), best:L('November to April; the park typically closes during the monsoon, so check the official season calendar.','நவம்பர் முதல் ஏப்ரல் வரை; பருவமழையில் பூங்கா பொதுவாக மூடப்படும், எனவே அதிகாரப்பூர்வ பருவ அட்டவணையைப் பார்க்கவும்.','नवंबर से अप्रैल; मानसून में पार्क आम तौर पर बंद रहता है, इसलिए आधिकारिक मौसम कैलेंडर जाँचें.'), weather:L('Typical winter daytime 20–28°C and nights 8–15°C; mornings can be misty.','குளிர்காலத்தில் பகலில் பொதுவாக 20–28°C, இரவில் 8–15°C; காலையில் மூடுபனி இருக்கலாம்.','सर्दियों में दिन आम तौर पर 20–28°C और रात 8–15°C; सुबह धुंध हो सकती है.'), source:'https://assamtourism.gov.in/Kaziranga1.php', sourceName:'Assam Tourism · Kaziranga', photo:'https://images.unsplash.com/photo-1561731216-c3a4d99437d5?w=1200&q=85', photoCredit:'Representative wildlife image · Unsplash', extra:L('Safari vehicles, entry permits and camera charges are separate unless written into the quote. Carry neutral clothing, binoculars if available, and follow the guide’s instructions.','விலைப்பட்டியலில் எழுத்துப்பூர்வமாக சேர்க்கப்படாவிட்டால் சஃபாரி வாகனம், நுழைவு அனுமதி மற்றும் கேமரா கட்டணம் தனியாகும். மிதமான நிற உடை, தொலைநோக்கி இருந்தால் அதையும் எடுத்துச் சென்று வழிகாட்டியின் அறிவுறுத்தலைப் பின்பற்றவும்.','कोटेशन में लिखित रूप से शामिल न होने पर सफ़ारी वाहन, प्रवेश परमिट और कैमरा शुल्क अलग हैं। हल्के रंग के कपड़े, उपलब्ध हो तो दूरबीन रखें और गाइड के निर्देश मानें.'), stops:[
    [L('Kohora safari gate','कोहोरा सफ़ारी गेट','कोहोरा सफ़ारी द्वार'),L('The central visitor gateway for authorized safari zones and permit checks.','அனுமதிக்கப்பட்ட சஃபாரி பகுதிகளுக்கும் அனுமதி சரிபார்ப்புக்கும் மைய பார்வையாளர் நுழைவிடம்.','अधिकृत सफ़ारी ज़ोन और परमिट जाँच का केंद्रीय आगंतुक प्रवेश द्वार.')],
    [L('Kaziranga jeep safari zone','காசிரங்கா ஜீப் சஃபாரி பகுதி','काज़ीरंगा जीप सफ़ारी क्षेत्र'),L('A guided drive through grassland and wetland habitat in an authority-assigned zone.','அதிகாரிகள் ஒதுக்கும் பகுதியில் புல்வெளி மற்றும் ஈரநில வாழிடங்கள் வழியாக வழிகாட்டியுடன் செல்லும் பயணம்.','अधिकारी द्वारा तय क्षेत्र में घासभूमि और आर्द्रभूमि से गुजरती गाइडेड ड्राइव.')],
    [L('Kaziranga Orchid and Biodiversity Park','காசிரங்கா ஆர்க்கிட் மற்றும் உயிரினப் பூங்கா','काज़ीरंगा ऑर्किड और जैव विविधता पार्क'),L('A local visitor attraction showcasing orchids and regional plant diversity.','ஆர்க்கிட் மலர்களையும் பிராந்தியத் தாவரப் பன்மையையும் காட்டும் உள்ளூர் பார்வையாளர் இடம்.','ऑर्किड और क्षेत्रीय पौधों की विविधता दिखाने वाला स्थानीय आकर्षण.')],
    [L('Agoratoli safari gate','அகோராடோலி சஃபாரி நுழைவிடம்','अगोराटोली सफ़ारी द्वार'),L('An eastern park access point used for a second pre-booked safari zone when operating.','இயங்கும் காலத்தில் முன்பதிவு செய்யப்பட்ட இரண்டாவது சஃபாரி பகுதிக்கான கிழக்கு நுழைவிடம்.','संचालन अवधि में दूसरी पूर्व-बुक सफ़ारी ज़ोन के लिए पूर्वी प्रवेश बिंदु.')]
  ]},
  { id:'SP-LEI-WILD-WI-001', category:'Wildlife & Nature', type:'Wildlife & Nature Tours', region:'West India', states:['Gujarat'], destination:L('Gir National Park, Gujarat','கிர் தேசியப் பூங்கா, குஜராத்','गिर राष्ट्रीय उद्यान, गुजरात'), start:'Sasan Gir', end:'Sasan Gir', title:L('Gir Lion Landscape Safari Break','கிர் சிங்கங்களின் வாழிட சஃபாரி பயணம்','गिर शेर परिदृश्य सफ़ारी अवकाश'), overview:L('A conservation-aware wildlife stay in the Gir landscape. The schedule includes a pre-booked Gir safari zone, an interpretation visit at Devalia and a daylight stop at Kamleshwar Dam. Permits are limited and tied to the date and visitor identity; lion sightings are not guaranteed.','கிர் நிலப்பரப்பில் பாதுகாப்பை மதிக்கும் வனவிலங்கு பயணம். முன்பதிவு செய்யப்பட்ட கிர் சஃபாரி பகுதி, தேவாலியா விளக்க மைய வருகை மற்றும் கம்லேஷ்வர் அணையில் பகல் நிறுத்தம் இதில் உள்ளன. அனுமதிகள் குறைவானவை; தேதி மற்றும் பயணி அடையாளத்துடன் இணைக்கப்படும். சிங்கங்களைப் பார்ப்பது உறுதி அல்ல.','गिर परिदृश्य में संरक्षण-केंद्रित वन्यजीव प्रवास। योजना में पूर्व-बुक गिर सफ़ारी क्षेत्र, देवळिया व्याख्या स्थल और कमलेश्वर बाँध पर दिन का पड़ाव है। परमिट सीमित और तारीख व यात्री पहचान से जुड़े होते हैं; शेर दिखना निश्चित नहीं है।'), best:L('November to March; Gir is closed to visitors from 16 June to 15 October.','நவம்பர் முதல் மார்ச் வரை; ஜூன் 16 முதல் அக்டோபர் 15 வரை கிர் பார்வையாளர்களுக்கு மூடப்படும்.','नवंबर से मार्च; गिर 16 जून से 15 अक्टूबर तक आगंतुकों के लिए बंद रहता है.'), weather:L('Typical peak-season daytime 24–30°C and nights 10–18°C; dry days and cool mornings.','உச்ச பருவத்தில் பகலில் பொதுவாக 24–30°C, இரவில் 10–18°C; வறண்ட பகலும் குளிர்ந்த காலையும்.','मुख्य मौसम में दिन आम तौर पर 24–30°C और रात 10–18°C; दिन सूखे और सुबहें ठंडी.'), source:'https://gujarattourism.com/saurashtra/gir-somnath/gir-national-park.html', sourceName:'Gujarat Tourism · Gir National Park', photo:'https://images.unsplash.com/photo-1549366021-9f761d450615?w=1200&q=85', photoCredit:'Representative wildlife image · Unsplash', extra:L('Gir safari permits must be booked online through the official system and matched to the visitor’s photo ID. Devalia is a separate ticketed facility.','கிர் சஃபாரி அனுமதியை அதிகாரப்பூர்வ இணைய அமைப்பில் முன்பதிவு செய்து பயணியின் புகைப்பட அடையாளத்துடன் பொருத்த வேண்டும். தேவாலியா தனி சீட்டு வசதி.','गिर सफ़ारी परमिट आधिकारिक ऑनलाइन प्रणाली से बुक कर यात्री के फोटो ID से मिलाना होगा। देवळिया अलग टिकट वाला स्थल है.'), stops:[
    [L('Sasan Gir safari reception','சசன் கிர் சஃபாரி வரவேற்பகம்','सासन गिर सफ़ारी स्वागत केंद्र'),L('The official visitor point for checking permits and joining an assigned forest drive.','அனுமதிகளைச் சரிபார்த்து ஒதுக்கப்பட்ட வனப் பயணத்தில் சேரும் அதிகாரப்பூர்வ மையம்.','परमिट जाँच और तय वन ड्राइव में शामिल होने का आधिकारिक केंद्र.')],
    [L('Gir Interpretation Zone, Devalia','தேவாலியா கிர் விளக்கப் பகுதி','देवळिया गिर व्याख्या क्षेत्र'),L('A managed interpretation area with a separate entry system and wildlife viewing circuit.','தனி நுழைவு முறையும் வனவிலங்கு பார்வைச் சுற்றும் கொண்ட நிர்வகிக்கப்பட்ட விளக்கப் பகுதி.','अलग प्रवेश प्रणाली और वन्यजीव दर्शन चक्र वाला प्रबंधित व्याख्या क्षेत्र.')],
    [L('Kamleshwar Dam viewpoint','கம்லேஷ்வர் அணைக் காட்சியிடம்','कमलेश्वर बाँध दृश्य स्थल'),L('A reservoir viewpoint in the sanctuary landscape; access follows the operating safari route.','சரணாலய நிலப்பரப்பிலுள்ள நீர்த்தேக்கக் காட்சியிடம்; இயங்கும் சஃபாரி வழிக்கேற்ப அணுகல்.','अभयारण्य परिदृश्य का जलाशय दृश्य स्थल; पहुँच चालू सफ़ारी मार्ग के अनुसार है.')],
    [L('Gir forest edge nature interpretation stop','கிர் வன எல்லை இயற்கை விளக்க நிறுத்தம்','गिर वन किनारा प्रकृति व्याख्या पड़ाव'),L('A guided orientation on dry deciduous forest, animal tracks and responsible viewing.','இலையுதிர் வனம், விலங்கு தடங்கள் மற்றும் பொறுப்பான பார்வை குறித்து வழிகாட்டியுடன் அறிமுகம்.','शुष्क पर्णपाती वन, पशु पदचिह्न और जिम्मेदार अवलोकन पर गाइडेड परिचय.')]
  ]},

  { id:'SP-LEI-ADV-TN-001', category:'Adventure & Trekking', type:'Adventure & Trekking Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Kolli Hills, Tamil Nadu','கொல்லிமலை, தமிழ்நாடு','कोल्ली हिल्स, तमिलनाडु'), start:'Semmedu', end:'Semmedu', title:L('Kolli Hills Viewpoints & Waterfall Walk','கொல்லிமலை காட்சியிடங்கள் மற்றும் அருவி நடை','कोल्ली हिल्स दृश्य स्थल और झरना पदयात्रा'), overview:L('An active hill weekend in Namakkal district, with a carefully paced waterfall walk and scenic road stops. Day one visits the Horticulture Farm and Seekuparai viewpoint; day two is reserved for the Agaya Gangai Falls approach and a rest stop at the boat-house area. The waterfall route includes many steps and may close during heavy rain.','நாமக்கல் மாவட்டத்தில் அமைந்த சுறுசுறுப்பான மலை வார இறுதி. திட்டமிட்ட வேகத்தில் அருவி நடை மற்றும் சாலை காட்சியிடங்கள் உள்ளன. முதல் நாள் தோட்டக்கலைப் பண்ணை மற்றும் சீக்குப்பாறை காட்சியிடம்; இரண்டாம் நாள் ஆகாயகங்கை அருவிப் பாதையும் படகு இல்லம் அருகிலான ஓய்வும். அருவிப் பாதையில் பல படிகள் உள்ளன; கனமழையில் மூடப்படலாம்.','नामक्कल ज़िले में सक्रिय पहाड़ी सप्ताहांत, जिसमें नियंत्रित गति की झरना पदयात्रा और सुंदर सड़क पड़ाव हैं। पहले दिन बागवानी फ़ार्म और सीकुपराई दृश्य स्थल; दूसरे दिन अगाया गंगई झरने का मार्ग और बोटहाउस क्षेत्र में विश्राम। झरने तक कई सीढ़ियाँ हैं और भारी बारिश में मार्ग बंद हो सकता है।'), best:L('October to February for cooler, clearer trails; avoid heavy monsoon rain.','குளிர்ச்சியான தெளிவான பாதைகளுக்கு அக்டோபர் முதல் பிப்ரவரி வரை; கனமழைப் பருவத்தைத் தவிர்க்கவும்.','ठंडे और साफ़ रास्तों के लिए अक्टूबर से फरवरी; तेज़ मानसूनी बारिश से बचें.'), weather:L('Typical peak-season daytime 18–26°C and nights 12–18°C; humid after rain.','உச்ச பருவத்தில் பகலில் பொதுவாக 18–26°C, இரவில் 12–18°C; மழைக்குப் பின் ஈரப்பதம் அதிகம்.','मुख्य मौसम में दिन आम तौर पर 18–26°C और रात 12–18°C; बारिश के बाद उमस रहती है.'), source:'https://namakkal.nic.in/tourist-place/kolli-hills/', sourceName:'Namakkal District · Kolli Hills', photo:'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=1200&q=85', photoCredit:'Representative mountain image · Unsplash', extra:L('Agaya Gangai involves a steep stair descent and return climb; wear grippy footwear and carry water. Waterfall access can be restricted by rain or local orders.','ஆகாயகங்கை செல்ல செங்குத்தான படிக்கட்டுகள் வழியாக இறங்கி மீண்டும் ஏற வேண்டும்; பிடிப்புள்ள காலணி மற்றும் தண்ணீர் எடுத்துச் செல்லவும். மழை அல்லது உள்ளூர் உத்தரவால் அணுகல் கட்டுப்படலாம்.','अगाया गंगई तक जाने में खड़ी सीढ़ियों से उतरना और वापस चढ़ना है; अच्छी पकड़ वाले जूते और पानी रखें। बारिश या स्थानीय आदेश से पहुँच सीमित हो सकती है.'), stops:[
    [L('Kolli Hills Horticulture Farm','கொல்லிமலை தோட்டக்கலைப் பண்ணை','कोल्ली हिल्स बागवानी फ़ार्म'),L('A government horticulture site with hill-grown fruit and plant displays; confirm public visiting hours.','மலைப் பழங்கள் மற்றும் தாவரக் காட்சியுடன் கூடிய அரசு தோட்டக்கலைத் தளம்; பொதுமக்கள் வருகை நேரத்தைச் சரிபார்க்கவும்.','पहाड़ी फल और पौधों के प्रदर्शन वाला सरकारी बागवानी स्थल; सार्वजनिक भ्रमण समय की पुष्टि करें.')],
    [L('Seekuparai viewpoint','சீக்குப்பாறை காட்சியிடம்','सीकुपराई दृश्य स्थल'),L('A roadside lookout across the Eastern Ghats ridges and surrounding valleys.','கிழக்குத் தொடர்ச்சி மலை முகடுகள் மற்றும் பள்ளத்தாக்குகளைப் பார்க்கும் சாலையோர இடம்.','पूर्वी घाट की पर्वत धाराओं और घाटियों का सड़क किनारे दृश्य स्थल.')],
    [L('Agaya Gangai Falls stair trail','ஆகாயகங்கை அருவிப் படிக்கட்டுப் பாதை','अगाया गंगई झरना सीढ़ी मार्ग'),L('A long stair route descends to the waterfall basin; the return climb is physically demanding.','நீண்ட படிக்கட்டுப் பாதை அருவித் தொட்டிக்குச் செல்கிறது; திரும்பும் ஏற்றம் உடல் உழைப்பு அதிகம்.','लंबी सीढ़ियाँ झरने के कुंड तक उतरती हैं; वापसी की चढ़ाई शारीरिक रूप से कठिन है.')],
    [L('Vasalurpatty boat-house area','வாசலூர்பட்டி படகு இல்லப் பகுதி','वासलूरपट्टी बोटहाउस क्षेत्र'),L('A managed lakeside recreation area; boating runs only when local operators are open.','உள்ளூர் இயக்குநர்கள் திறந்திருக்கும் நேரத்தில் மட்டுமே படகு சேவை நடைபெறும் நிர்வகிக்கப்பட்ட ஏரிக்கரை பகுதி.','प्रबंधित झील किनारे का मनोरंजन क्षेत्र; नौकायन केवल स्थानीय संचालक खुला होने पर चलता है.')]
  ]},
  { id:'SP-LEI-ADV-NI-001', category:'Adventure & Trekking', type:'Adventure & Trekking Tours', region:'North India', states:['Uttarakhand'], destination:L('Rishikesh, Uttarakhand','ரிஷிகேஷ், உத்தரகாண்ட்','ऋषिकेश, उत्तराखंड'), start:'Rishikesh', end:'Rishikesh', title:L('Rishikesh River & Waterfall Adventure','ரிஷிகேஷ் ஆறு மற்றும் அருவி சாகசப் பயணம்','ऋषिकेश नदी और झरना रोमांच यात्रा'), overview:L('An outdoor-focused Rishikesh itinerary with a regulated rafting session and a short waterfall walk. Day one is dedicated to the authorized rafting stretch and safety briefing; day two visits Neer Garh Falls and a riverside rest area. Rafting is seasonal, age and health restricted, and operated only by approved providers.','அங்கீகரிக்கப்பட்ட ராஃப்டிங் பயணமும் குறுகிய அருவி நடைபயணமும் கொண்ட ரிஷிகேஷ் வெளிப்புறச் செயல்பாட்டு திட்டம். முதல் நாள் அனுமதிக்கப்பட்ட ராஃப்டிங் பாதையும் பாதுகாப்பு விளக்கமும்; இரண்டாம் நாள் நீர் கர் அருவி மற்றும் ஆற்றங்கரை ஓய்வு. ராஃப்டிங் பருவகாலமானது; வயது மற்றும் உடல்நலக் கட்டுப்பாடுகள் உண்டு; அங்கீகரிக்கப்பட்ட இயக்குநர்கள் மட்டுமே நடத்துவர்.','ऋषिकेश की आउटडोर यात्रा में अनुमोदित राफ्टिंग और छोटी झरना पदयात्रा है। पहले दिन अधिकृत राफ्टिंग मार्ग और सुरक्षा परिचय; दूसरे दिन नीरगढ़ झरना और नदी किनारे विश्राम। राफ्टिंग मौसमी है, उम्र व स्वास्थ्य नियम लागू हैं और केवल स्वीकृत संचालक इसे चलाते हैं।'), best:L('September to June for rafting; October to April is usually more comfortable for walking.','ராஃப்டிங்கிற்கு செப்டம்பர் முதல் ஜூன் வரை; நடைப்பயணத்திற்கு அக்டோபர் முதல் ஏப்ரல் வரை பொதுவாக வசதி.','राफ्टिंग के लिए सितंबर से जून; पैदल घूमने के लिए अक्टूबर से अप्रैल आम तौर पर अधिक आरामदायक.'), weather:L('Typical peak-season daytime 20–30°C and nights 8–18°C; sunny afternoons, cool mornings.','உச்ச பருவத்தில் பகலில் பொதுவாக 20–30°C, இரவில் 8–18°C; வெயிலான பிற்பகல், குளிர்ந்த காலை.','मुख्य मौसम में दिन आम तौर पर 20–30°C और रात 8–18°C; धूप वाली दोपहर और ठंडी सुबहें.'), source:'https://www.uttarakhandtourism.gov.in/adventures/river-rafting', sourceName:'Uttarakhand Tourism · River rafting', photo:'https://images.unsplash.com/photo-1530789253388-582c481c54b0?w=1200&q=85', photoCredit:'Representative river adventure image · Unsplash', extra:L('Use an authorized rafting operator and its supplied life jacket and helmet. Rafting is not suitable for everyone; disclose health conditions and follow age, weight and weather restrictions.','அங்கீகரிக்கப்பட்ட ராஃப்டிங் இயக்குநரையும் அவர் வழங்கும் உயிர்காப்பு ஜாக்கெட் மற்றும் தலைக்கவசத்தையும் பயன்படுத்தவும். இது அனைவருக்கும் ஏற்றதல்ல; உடல்நல நிலையைத் தெரிவித்து வயது, எடை மற்றும் வானிலை விதிகளைப் பின்பற்றவும்.','अधिकृत राफ्टिंग संचालक और उसके दिए लाइफ़ जैकेट व हेलमेट का उपयोग करें। राफ्टिंग सभी के लिए उपयुक्त नहीं; स्वास्थ्य स्थिति बताएँ और उम्र, वज़न व मौसम नियम मानें.'), stops:[
    [L('Shivpuri rafting launch point','சிவ்புரி ராஃப்டிங் தொடக்க இடம்','शिवपुरी राफ्टिंग प्रारंभ स्थल'),L('A designated launch area for operator-led rafting on the Ganga, subject to river conditions.','கங்கை ஆற்றில் இயக்குநர் நடத்தும் ராஃப்டிங்கிற்கான குறிப்பிட்ட தொடக்க இடம்; ஆற்றுச் சூழ்நிலைக்கு உட்பட்டது.','गंगा में संचालक-नेतृत्व वाली राफ्टिंग का निर्धारित आरंभ स्थल; नदी की स्थिति पर निर्भर.')],
    [L('Rishikesh rafting finish ghat','ரிஷிகேஷ் ராஃப்டிங் நிறைவு கரை','ऋषिकेश राफ्टिंग समापन घाट'),L('The operator’s designated take-out point and equipment return area.','இயக்குநர் குறிக்கும் இறங்கும் இடமும் உபகரணங்களைத் திருப்பித் தரும் பகுதியும்.','संचालक द्वारा तय उतरने का स्थान और उपकरण लौटाने का क्षेत्र.')],
    [L('Neer Garh Waterfall trail','நீர் கர் அருவிப் பாதை','नीरगढ़ झरना मार्ग'),L('A stepped hillside trail reaches a series of small cascades; surfaces can be slippery.','படிகள் கொண்ட மலைப்பாதை சிறிய அருவித் தொடர்களை அடைகிறது; தரை வழுக்கலாக இருக்கலாம்.','सीढ़ियों वाला पहाड़ी मार्ग छोटे झरनों तक पहुँचता है; सतह फिसलन भरी हो सकती है.')],
    [L('Kaudiyala river-view stop','கௌடியாலா ஆற்றுக் காட்சியிடம்','कौड़ियाला नदी दृश्य पड़ाव'),L('A roadside river overlook for a short rest and view of the valley; remain behind barriers.','சிறிய ஓய்வுக்கும் பள்ளத்தாக்குக் காட்சிக்கும் சாலையோர ஆற்றுப் பார்வை; பாதுகாப்புத் தடையைத் தாண்ட வேண்டாம்.','घाटी के दृश्य और छोटे विश्राम के लिए सड़क किनारे नदी दृश्य स्थल; सुरक्षा अवरोध के पीछे रहें.')]
  ]},
  { id:'SP-LEI-ADV-NI-002', category:'Adventure & Trekking', type:'Adventure & Trekking Tours', region:'North India', states:['Himachal Pradesh'], destination:L('Bir and Billing, Himachal Pradesh','பீர் மற்றும் பில்லிங், இமாச்சலப் பிரதேசம்','बीर और बिलिंग, हिमाचल प्रदेश'), start:'Bir', end:'Bir', title:L('Bir Billing Paragliding & Valley Trek','பீர் பில்லிங் பாராகிளைடிங் மற்றும் பள்ளத்தாக்கு நடை','बीर बिलिंग पैराग्लाइडिंग और घाटी ट्रेक'), overview:L('A mountain activity weekend based in Bir, pairing a licensed tandem paragliding flight with a guided lower-valley walk. Day one covers the Billing take-off site and Bir landing area; day two follows a gentle trail toward Rajgundha valley’s accessible approach. Flight operations depend on wind, cloud and licensed pilot availability.','பீரை மையமாகக் கொண்ட மலைச் செயல்பாட்டு வார இறுதி; உரிமம் பெற்ற டாண்டம் பாராகிளைடிங் பறப்பையும் கீழ் பள்ளத்தாக்கு வழிகாட்டி நடைபயணத்தையும் இணைக்கிறது. முதல் நாள் பில்லிங் புறப்பாட்டு இடம் மற்றும் பீர் இறங்குமிடம்; இரண்டாம் நாள் ராஜ்குண்டா பள்ளத்தாக்கின் எளிதான அணுகுமுறை வரை நடை. காற்று, மேகம் மற்றும் உரிமம் பெற்ற விமானி கிடைப்பைச் சார்ந்து பறப்பு நடைபெறும்.','बीर में ठहरकर पर्वतीय गतिविधियों का सप्ताहांत, जिसमें लाइसेंस प्राप्त टैंडम पैराग्लाइडिंग और निचली घाटी में गाइडेड वॉक है। पहले दिन बिलिंग टेक-ऑफ़ स्थल और बीर लैंडिंग क्षेत्र; दूसरे दिन राजगुंधा घाटी के सुलभ हिस्से तक हल्का ट्रेक। उड़ान हवा, बादल और लाइसेंस प्राप्त पायलट की उपलब्धता पर निर्भर है।'), best:L('October to June; October–November and March–May often have clearer flying windows.','அக்டோபர் முதல் ஜூன் வரை; அக்டோபர்–நவம்பர் மற்றும் மார்ச்–மே மாதங்களில் பறப்பதற்கு தெளிவு அதிகம்.','अक्टूबर से जून; अक्टूबर–नवंबर और मार्च–मई में उड़ान के लिए अक्सर साफ़ मौसम मिलता है.'), weather:L('Typical daytime 12–24°C and nights 3–12°C; cold at Billing and changeable mountain winds.','பகலில் பொதுவாக 12–24°C, இரவில் 3–12°C; பில்லிங்கில் குளிர் மற்றும் மாறும் மலைக் காற்று.','दिन आम तौर पर 12–24°C और रात 3–12°C; बिलिंग में ठंड और पहाड़ी हवा बदलती रहती है.'), source:'https://himachaltourism.gov.in/destination/paragliding/', sourceName:'Himachal Tourism · Paragliding', photo:'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=1200&q=85', photoCredit:'Representative mountain landscape · Unsplash', extra:L('Fly only with a registered operator and qualified tandem pilot. Weight, age, health, wind and visibility restrictions apply; activity price and transfer to Billing are confirmed separately.','பதிவுசெய்யப்பட்ட இயக்குநர் மற்றும் தகுதியான டாண்டம் விமானியுடன் மட்டுமே பறக்கவும். எடை, வயது, உடல்நலம், காற்று மற்றும் தெளிவு கட்டுப்பாடுகள் உண்டு; செயல்பாட்டு விலை மற்றும் பில்லிங் இடமாற்றம் தனியாக உறுதியாகும்.','केवल पंजीकृत संचालक और योग्य टैंडम पायलट के साथ उड़ें। वज़न, उम्र, स्वास्थ्य, हवा और दृश्यता नियम लागू हैं; गतिविधि शुल्क और बिलिंग तक वाहन अलग से पक्का होगा.'), stops:[
    [L('Billing paragliding take-off site','பில்லிங் பாராகிளைடிங் புறப்பாட்டு இடம்','बिलिंग पैराग्लाइडिंग टेक-ऑफ़ स्थल'),L('A high-altitude launch meadow reached by a mountain road; flights begin only after pilot clearance.','மலைச் சாலை வழியாகச் செல்லும் உயரமான புறப்பாட்டு புல்வெளி; விமானி அனுமதித்த பிறகே பறப்பு தொடங்கும்.','पहाड़ी सड़क से पहुँचा जाने वाला ऊँचाई का लॉन्च मैदान; पायलट की अनुमति के बाद ही उड़ान शुरू होती है.')],
    [L('Bir landing site','பீர் இறங்குமிடம்','बीर लैंडिंग स्थल'),L('The designated landing field used by tandem pilots, with a post-flight equipment check.','டாண்டம் விமானிகள் பயன்படுத்தும் குறிப்பிட்ட தரையிறங்கும் புலம்; பறப்புக்குப் பின் உபகரணச் சரிபார்ப்பு நடைபெறும்.','टैंडम पायलटों का निर्धारित लैंडिंग मैदान, जहाँ उड़ान के बाद उपकरण जाँचे जाते हैं.')],
    [L('Bir tea-garden walking lane','பீர் தேயிலைத் தோட்ட நடைபாதை','बीर चाय बागान पैदल मार्ग'),L('A gentle rural walk beside cultivated fields and views toward the Dhauladhar range.','பயிரிடப்பட்ட வயல்களோரம் தவுலாதார் மலைத்தொடரை நோக்கும் எளிய கிராமப்புற நடை.','खेती के खेतों के पास धौलाधार पर्वतमाला की ओर दृश्य वाला हल्का ग्रामीण पैदल मार्ग.')],
    [L('Rajgundha valley approach trail','ராஜ்குண்டா பள்ளத்தாக்கு அணுகுமுறை நடைபாதை','राजगुंधा घाटी प्रवेश ट्रेल'),L('A guided out-and-back valley walk; the turnaround point is set to the group’s pace and conditions.','குழு வேகம் மற்றும் சூழ்நிலைக்கு ஏற்ப திரும்பும் இடத்தை நிர்ணயிக்கும் வழிகாட்டியுடன் செல்லும் பள்ளத்தாக்கு நடை.','समूह की गति और परिस्थितियों के अनुसार वापसी बिंदु तय करने वाला गाइडेड घाटी ट्रेक.')]
  ]},

  { id:'SP-LEI-HILL-TN-001', category:'Hill Stations & Leisure', type:'Hill Station & Leisure Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Yercaud, Tamil Nadu','ஏற்காடு, தமிழ்நாடு','येरकौड, तमिलनाडु'), start:'Yercaud', end:'Yercaud', title:L('Yercaud Lake & Coffee Hills Leisure Break','ஏற்காடு ஏரி மற்றும் காபி மலை ஓய்வுப் பயணம்','येरकौड झील और कॉफ़ी पहाड़ियाँ अवकाश'), overview:L('A relaxed hill-station stay built around Yercaud’s lake, gardens and viewpoints. Day one pairs the lakefront with the Botanical Garden; day two visits Lady’s Seat and Kiliyur Falls, keeping the waterfall walk in the cooler morning. The itinerary is entirely within Tamil Nadu.','ஏற்காட்டின் ஏரி, தோட்டம் மற்றும் காட்சியிடங்களை மையமாகக் கொண்ட நிதானமான மலைவாசஸ்தலப் பயணம். முதல் நாள் ஏரிக்கரை மற்றும் தாவரவியல் பூங்கா; இரண்டாம் நாள் லேடீஸ் சீட் மற்றும் கிளியூர் அருவி, அருவி நடை குளிர்ந்த காலையில் அமைக்கப்பட்டுள்ளது. முழுப் பயணமும் தமிழ்நாட்டிற்குள்.','येरकौड की झील, बगीचों और दृश्य स्थलों पर आधारित आरामदायक हिल स्टेशन यात्रा। पहले दिन झील किनारा और वनस्पति उद्यान; दूसरे दिन लेडीज़ सीट और किलियूर झरना, जिसकी पैदल यात्रा ठंडी सुबह रखी गई है। पूरा मार्ग तमिलनाडु के भीतर है।'), best:L('October to June; November to February is cooler, while summer mornings are pleasant.','அக்டோபர் முதல் ஜூன் வரை; நவம்பர் முதல் பிப்ரவரி வரை குளிர்ச்சியானது, கோடைக் காலைக் நேரங்கள் இனிமையானவை.','अक्टूबर से जून; नवंबर से फरवरी ठंडा रहता है और गर्मियों की सुबहें सुहावनी होती हैं.'), weather:L('Typical peak-season daytime 13–27°C and nights 10–17°C; mild hill weather with occasional mist.','உச்ச பருவத்தில் பகலில் பொதுவாக 13–27°C, இரவில் 10–17°C; மிதமான மலை வானிலை, அவ்வப்போது மூடுபனி.','मुख्य मौसम में दिन आम तौर पर 13–27°C और रात 10–17°C; हल्का पहाड़ी मौसम और कभी-कभी धुंध.'), source:'https://www.prod.incredibleindia.gov.in/content/incredible-india-v2/en/destinations/yercaud.html', sourceName:'Incredible India · Yercaud', photo:'https://upload.wikimedia.org/wikipedia/commons/6/64/Yercaud_Lake_Panorama.jpg', photoCredit:'Yercaud Lake Panorama · Wikimedia Commons', extra:L('Kiliyur Falls has a steep descent and can be closed after heavy rain. Boating and garden entry follow local operating hours and are ticketed separately.','கிளியூர் அருவிக்குச் செங்குத்தான இறக்கம் உண்டு; கனமழைக்குப் பின் மூடப்படலாம். படகு மற்றும் தோட்ட நுழைவு உள்ளூர் நேரப்படி, தனி சீட்டுடன்.','किलियूर झरने तक खड़ी उतराई है और भारी बारिश के बाद बंद हो सकता है। नौकायन और उद्यान प्रवेश स्थानीय समय के अनुसार तथा अलग टिकट पर हैं.'), stops:[
    [L('Yercaud Lake and boat house','ஏற்காடு ஏரி மற்றும் படகு இல்லம்','येरकौड झील और बोटहाउस'),L('A central hill lake with a public walking edge and ticketed boating when operating.','பொதுநடைப் பாதையும் இயங்கும் நேரத்தில் சீட்டுடன் படகு சேவையும் கொண்ட மலை ஏரி.','सार्वजनिक तट मार्ग और संचालन के समय टिकट वाली नौकायन सुविधा सहित केंद्रीय पहाड़ी झील.')],
    [L('Yercaud Botanical Garden','ஏற்காடு தாவரவியல் பூங்கா','येरकौड वनस्पति उद्यान'),L('A landscaped collection of local and ornamental plants with short marked paths.','உள்ளூர் மற்றும் அலங்காரத் தாவரங்களுடன் குறுகிய குறிக்கப்பட்ட பாதைகள் கொண்ட தோட்டம்.','स्थानीय और सजावटी पौधों का उद्यान, जिसमें छोटे चिह्नित रास्ते हैं.')],
    [L('Lady’s Seat viewpoint','லேடீஸ் சீட் காட்சியிடம்','लेडीज़ सीट दृश्य स्थल'),L('A hill-edge lookout over Salem plains, with the clearest views on dry mornings.','சேலம் சமவெளியை நோக்கும் மலை விளிம்பு காட்சியிடம்; வறண்ட காலை நேரத்தில் தெளிவான காட்சி.','सेलम मैदानों की ओर पहाड़ी किनारे का दृश्य स्थल; सूखी सुबहों में दृश्य अधिक साफ़.')],
    [L('Kiliyur Falls trailhead','கிளியூர் அருவிப் பாதை தொடக்கம்','किलियूर झरना ट्रेलहेड'),L('The marked access to a seasonal waterfall; the steep stair return requires reasonable fitness.','பருவகால அருவிக்கான குறிக்கப்பட்ட வழி; செங்குத்தான படிக்கட்டு ஏற்றத்திற்குச் சராசரி உடற்தகுதி தேவை.','मौसमी झरने का चिह्नित मार्ग; खड़ी सीढ़ियों से लौटने के लिए सामान्य फिटनेस चाहिए.')]
  ]},
  { id:'SP-LEI-HILL-SI-001', category:'Hill Stations & Leisure', type:'Hill Station & Leisure Tours', region:'South India', states:['Karnataka'], destination:L('Chikkamagaluru, Karnataka','சிக்கமகளூரு, கர்நாடகா','चिक्कमगलुरु, कर्नाटक'), start:'Chikkamagaluru', end:'Chikkamagaluru', title:L('Chikkamagaluru Coffee Hills & Lake Retreat','சிக்கமகளூரு காபி மலைகள் மற்றும் ஏரி ஓய்வு','चिक्कमगलुरु कॉफ़ी पहाड़ियाँ और झील अवकाश'), overview:L('A restful coffee-country stay with a scenic peak drive and lakeside time. Day one visits Hirekolale Lake and a guided coffee estate; day two takes the group to Mullayanagiri’s accessible viewpoint and a short garden stop. The route avoids a long trek and leaves time for the return drive.','அழகிய மலைச் சாலைப் பயணமும் ஏரிக்கரை ஓய்வும் கொண்ட காபி நிலப் பயணம். முதல் நாள் ஹிரேகொலாலே ஏரி மற்றும் வழிகாட்டியுடன் காபித் தோட்டம்; இரண்டாம் நாள் முல்லையனகிரியின் அணுகக்கூடிய காட்சியிடம் மற்றும் குறுகிய தோட்ட நிறுத்தம். நீண்ட மலையேற்றம் தவிர்க்கப்பட்டு திரும்பும் பயணத்திற்கும் நேரம் விடப்பட்டுள்ளது.','सुंदर पहाड़ी ड्राइव और झील किनारे विश्राम वाला कॉफ़ी क्षेत्र प्रवास। पहले दिन हिरेकोलाले झील और गाइडेड कॉफ़ी बागान; दूसरे दिन मुल्लयनगिरि का सुलभ दृश्य स्थल और छोटा उद्यान पड़ाव। लंबा ट्रेक नहीं रखा गया है और वापसी ड्राइव के लिए समय छोड़ा है।'), best:L('October to March; December to February has cool mornings and clearer hill views.','அக்டோபர் முதல் மார்ச் வரை; டிசம்பர் முதல் பிப்ரவரி வரை குளிர்ந்த காலை மற்றும் தெளிவான மலைக் காட்சி.','अक्टूबर से मार्च; दिसंबर से फरवरी में ठंडी सुबह और पहाड़ी दृश्य अधिक साफ़ रहते हैं.'), weather:L('Typical peak-season daytime 18–28°C and nights 12–18°C; cool at higher viewpoints.','உச்ச பருவத்தில் பகலில் பொதுவாக 18–28°C, இரவில் 12–18°C; உயரமான காட்சியிடங்களில் குளிர்.','मुख्य मौसम में दिन आम तौर पर 18–28°C और रात 12–18°C; ऊँचे दृश्य स्थलों पर ठंड.'), source:'https://karnatakatourism.org/en/destinations/chikkamagalur', sourceName:'Karnataka Tourism · Chikkamagaluru', photo:'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=1200&q=85', photoCredit:'Representative mountain lake image · Unsplash', extra:L('Mullayanagiri access can be restricted by fog, wind or parking controls. The coffee estate walk requires advance permission and is confirmed separately.','மூடுபனி, காற்று அல்லது வாகன நிறுத்தக் கட்டுப்பாடால் முல்லையனகிரி அணுகல் மாறலாம். காபித் தோட்ட நடைபயணத்திற்கு முன் அனுமதி தேவை; தனியாக உறுதிப்படுத்தப்படும்.','कोहरे, हवा या पार्किंग नियंत्रण से मुल्लयनगिरि की पहुँच सीमित हो सकती है। कॉफ़ी बागान भ्रमण के लिए अग्रिम अनुमति चाहिए और अलग से पुष्टि होगी.'), stops:[
    [L('Hirekolale Lake','ஹிரேகொலாலே ஏரி','हिरेकोलाले झील'),L('A reservoir-side viewpoint framed by coffee hills; swimming is not part of the visit.','காபி மலைகளால் சூழப்பட்ட நீர்த்தேக்கக் காட்சியிடம்; நீச்சல் வருகையில் இல்லை.','कॉफ़ी पहाड़ियों से घिरा जलाशय दृश्य स्थल; तैराकी यात्रा में शामिल नहीं है.')],
    [L('Chikkamagaluru coffee estate walk','சிக்கமகளூரு காபித் தோட்ட நடை','चिक्कमगलुरु कॉफ़ी बागान सैर'),L('A permission-based guided walk through shade coffee plants and estate paths.','நிழல் காபிச் செடிகள் மற்றும் தோட்டப் பாதைகள் வழியாக அனுமதியுடன் நடைபெறும் வழிகாட்டி நடை.','छाया में उगाई कॉफ़ी और बागान पगडंडियों पर अनुमति-आधारित गाइडेड वॉक.')],
    [L('Mullayanagiri accessible viewpoint','முல்லையனகிரி அணுகக்கூடிய காட்சியிடம்','मुल्लयनगिरि सुलभ दृश्य स्थल'),L('A high Western Ghats viewpoint reached by road and a short stepped approach.','சாலை வழியாகச் சென்று குறுகிய படிப்பாதை கொண்ட உயரமான மேற்குத் தொடர்ச்சி மலைக் காட்சியிடம்.','सड़क और थोड़ी सीढ़ियों से पहुँचा जाने वाला पश्चिमी घाट का ऊँचा दृश्य स्थल.')],
    [L('Coffee Museum, Chikkamagaluru','சிக்கமகளூரு காபி அருங்காட்சியகம்','चिक्कमगलुरु कॉफ़ी संग्रहालय'),L('A compact indoor stop on coffee growing and processing; opening hours are checked locally.','காபி சாகுபடி மற்றும் பதப்படுத்தல் குறித்த சிறிய உள்ளரங்கு; திறப்பு நேரம் உள்ளூரில் சரிபார்க்கப்படும்.','कॉफ़ी की खेती और प्रसंस्करण पर छोटा इनडोर स्थल; खुलने का समय स्थानीय रूप से जाँचा जाएगा.')]
  ]},
  { id:'SP-LEI-HILL-NE-001', category:'Hill Stations & Leisure', type:'Hill Station & Leisure Tours', region:'Northeast India', states:['Meghalaya'], destination:L('Shillong, Meghalaya','ஷில்லாங், மேகாலயா','शिलांग, मेघालय'), start:'Shillong', end:'Shillong', title:L('Shillong Lakes, Gardens & Falls','ஷில்லாங் ஏரிகள், தோட்டங்கள் மற்றும் அருவிகள்','शिलांग झीलें, उद्यान और झरने'), overview:L('A gentle Shillong city-and-nature stay with limited driving each day. Day one visits Ward’s Lake and the Umiam Lake viewpoint; day two visits Elephant Falls and Shillong Peak when access is open. Rain showers can arrive quickly, so the afternoon plan remains flexible.','ஒவ்வொரு நாளும் குறைந்த வாகனப் பயணத்துடன் அமைந்த ஷில்லாங் நகரம் மற்றும் இயற்கைத் தங்கல். முதல் நாள் வார்ட்ஸ் ஏரி மற்றும் உமியம் ஏரிக் காட்சியிடம்; இரண்டாம் நாள் அணுகல் திறந்திருக்கும் போது எலிபண்ட் அருவி மற்றும் ஷில்லாங் சிகரம். மழை திடீரென வரலாம், எனவே பிற்பகல் திட்டம் நெகிழ்வாக இருக்கும்.','कम ड्राइव वाली शिलांग शहर और प्रकृति यात्रा। पहले दिन वार्ड्स लेक और उमियम झील दृश्य स्थल; दूसरे दिन पहुँच खुली होने पर एलिफेंट फॉल्स और शिलांग पीक। बारिश अचानक हो सकती है, इसलिए दोपहर का कार्यक्रम लचीला रहेगा।'), best:L('October to April; November to February is generally drier and cooler.','அக்டோபர் முதல் ஏப்ரல் வரை; நவம்பர் முதல் பிப்ரவரி வரை பொதுவாக வறட்சியும் குளிர்ச்சியும்.','अक्टूबर से अप्रैल; नवंबर से फरवरी आम तौर पर सूखा और ठंडा रहता है.'), weather:L('Typical peak-season daytime 10–22°C and nights 4–11°C; carry a light rain layer year-round.','உச்ச பருவத்தில் பகலில் பொதுவாக 10–22°C, இரவில் 4–11°C; ஆண்டு முழுவதும் மழை மேலாடை வைத்திருங்கள்.','मुख्य मौसम में दिन आम तौर पर 10–22°C और रात 4–11°C; पूरे साल हल्की वर्षा-परत साथ रखें.'), source:'https://www.meghalayatourism.in/plan/suggested-itineraries/itineraries/1-day/natural-tranquility-shillong/', sourceName:'Meghalaya Tourism · Shillong itinerary', photo:'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=1200&q=85', photoCredit:'Representative lake and hill image · Unsplash', extra:L('Carry rain protection and non-slip shoes. Waterfall steps and the Shillong Peak access gate can close in poor weather or for security controls.','மழை பாதுகாப்பும் வழுக்காத காலணியும் எடுத்துச் செல்லவும். மோசமான வானிலை அல்லது பாதுகாப்புக் கட்டுப்பாட்டால் அருவிப் படிகளும் ஷில்லாங் சிகர நுழைவாயிலும் மூடப்படலாம்.','वर्षा सुरक्षा और फिसलन-रोधी जूते रखें। खराब मौसम या सुरक्षा नियंत्रण से झरने की सीढ़ियाँ और शिलांग पीक प्रवेश बंद हो सकते हैं.'), stops:[
    [L('Ward’s Lake','வார்ட்ஸ் ஏரி','वार्ड्स लेक'),L('A central landscaped lake garden with a level path around the water.','நீரைச் சுற்றி சமமான நடைபாதை கொண்ட மைய ஏரித் தோட்டம்.','पानी के चारों ओर समतल पथ वाला केंद्रीय झील उद्यान.')],
    [L('Umiam Lake viewpoint','உமியம் ஏரிக் காட்சியிடம்','उमियम झील दृश्य स्थल'),L('A roadside overlook of the large reservoir and surrounding pine-covered hills.','பெரிய நீர்த்தேக்கத்தையும் பைன் மரों वाली पहाड़ियों को देखता सड़क किनारे कாட்சியிடம்.','बड़े जलाशय और चीड़ वाली पहाड़ियों का सड़क किनारे दृश्य स्थल.')],
    [L('Elephant Falls','எலிபண்ட் அருவி','एलिफेंट फॉल्स'),L('A three-tier waterfall reached by stairways; take care on wet steps.','படிகள் வழியாகச் செல்லும் மூன்று அடுக்கு அருவி; ஈரமான படிகளில் கவனம் தேவை.','सीढ़ियों से पहुँचा जाने वाला तीन-स्तरीय झरना; गीली सीढ़ियों पर सावधानी रखें.')],
    [L('Shillong Peak viewpoint','ஷில்லாங் சிகரக் காட்சியிடம்','शिलांग पीक दृश्य स्थल'),L('A high viewpoint above the city, subject to the access gate and clear visibility.','நகரத்திற்கு மேலுள்ள உயரமான காட்சியிடம்; நுழைவாயில் மற்றும் தெளிவான பார்வைக்கு உட்பட்டது.','शहर से ऊपर ऊँचा दृश्य स्थल; प्रवेश द्वार और साफ़ दृश्यता पर निर्भर है.')]
  ]},

  { id:'SP-LEI-BEACH-TN-001', category:'Beach & Coastal', type:'Beach & Coastal Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Covelong (Kovalam), Tamil Nadu','கோவளம் (கோவலாங்), தமிழ்நாடு','कोवलम (कोवलॉन्ग), तमिलनाडु'), start:'Covelong', end:'Covelong', title:L('Covelong Coast & Surf Introduction','கோவளம் கடற்கரை மற்றும் சர்ஃப் அறிமுகம்','कोवलम तट और सर्फ़ परिचय'), overview:L('A short coast break on Tamil Nadu’s Coromandel shore. Day one is a guided beginner surf lesson at Covelong with a long beach rest; day two visits the Muttukadu backwater boat-house area and returns for a coastal walk. Surf lessons, boards and water activities are optional and must be booked with a qualified operator.','தமிழ்நாட்டின் கொரமண்டல் கடற்கரையில் குறுகிய ஓய்வுப் பயணம். முதல் நாள் கோவளத்தில் தொடக்கநிலை சர்ஃப் பயிற்சியும் நீண்ட கடற்கரை ஓய்வும்; இரண்டாம் நாள் முட்டுக்காடு உப்பங்கழி படகு இல்லப் பகுதி மற்றும் கடலோர நடை. சர்ஃப் பயிற்சி, பலகை மற்றும் நீர்ச் செயல்பாடுகள் விருப்பத் தேர்வு; தகுதியான இயக்குநரிடம் முன்பதிவு செய்ய வேண்டும்.','तमिलनाडु के कोरोमंडल तट पर छोटा समुद्र अवकाश। पहले दिन कोवलम में शुरुआती सर्फ़ पाठ और लंबा बीच विश्राम; दूसरे दिन मुत्तुकाडु बैकवॉटर बोटहाउस क्षेत्र और तटीय सैर। सर्फ़ पाठ, बोर्ड और जल गतिविधियाँ वैकल्पिक हैं और योग्य संचालक से बुक करनी होंगी।'), best:L('November to February; mornings are cooler and sea conditions are usually gentler.','நவம்பர் முதல் பிப்ரவரி வரை; காலை நேரம் குளிர்ச்சியானது, கடல் நிலை பொதுவாக மென்மையானது.','नवंबर से फरवरी; सुबहें ठंडी और समुद्र की स्थिति आम तौर पर शांत रहती है.'), weather:L('Typical peak-season daytime 22–30°C and nights 20–24°C; humid, with a sea breeze.','உச்ச பருவத்தில் பகலில் பொதுவாக 22–30°C, இரவில் 20–24°C; ஈரப்பதமும் கடற்காற்றும்.','मुख्य मौसम में दिन आम तौर पर 22–30°C और रात 20–24°C; उमस और समुद्री हवा.'), source:'https://www.incredibleindia.gov.in/en/tamil-nadu/mamallapuram/mahabalipuram-beach', sourceName:'Incredible India · Mamallapuram coast', photo:'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85', photoCredit:'Representative coastal image · Unsplash', extra:L('Do not swim or surf without a qualified instructor and current sea-condition approval. Life jackets are required for boat rides; beach access can change with surf and local advisories.','தகுதியான பயிற்றுநரும் தற்போதைய கடல் நிலை அனுமதியும் இன்றி நீந்தவோ சர்ஃப் செய்யவோ வேண்டாம். படகு பயணத்திற்கு உயிர்காப்பு ஜாக்கெட் அவசியம்; அலை மற்றும் உள்ளூர் அறிவுறுத்தலால் கடற்கரை அணுகல் மாறலாம்.','योग्य प्रशिक्षक और वर्तमान समुद्री अनुमति के बिना तैरें या सर्फ़ न करें। नाव यात्रा में लाइफ़ जैकेट ज़रूरी है; लहर और स्थानीय सलाह से तट की पहुँच बदल सकती है.'), stops:[
    [L('Covelong Beach','கோவளம் கடற்கரை','कोवलम बीच'),L('A public sandy shore used for a supervised surf lesson and a daylight coastal walk.','கண்காணிக்கப்பட்ட சர்ஃப் பயிற்சி மற்றும் பகல் கடலோர நடைப்பயணத்திற்கான பொதுமணற்கரை.','निगरानी वाले सर्फ़ पाठ और दिन की तटीय सैर के लिए सार्वजनिक रेतीला तट.')],
    [L('Covelong surf school zone','கோவளம் சர்ஃப் பயிற்சி பகுதி','कोवलम सर्फ़ स्कूल क्षेत्र'),L('A lesson area used by local surf operators; board, instructor and safety gear are quoted separately.','உள்ளூர் சர்ஃப் இயக்குநர்கள் பயன்படுத்தும் பயிற்சி பகுதி; பலகை, பயிற்றுநர் மற்றும் பாதுகாப்பு உபகரணம் தனி விலை.','स्थानीय सर्फ़ संचालकों का पाठ क्षेत्र; बोर्ड, प्रशिक्षक और सुरक्षा उपकरण का शुल्क अलग है.')],
    [L('Muttukadu Boat House','முட்டுக்காடு படகு இல்லம்','मुत्तुकाडु बोटहाउस'),L('A backwater recreation jetty offering operator-run boating during posted hours.','அறிவிக்கப்பட்ட நேரங்களில் இயக்குநர் நடத்தும் படகு சேவை கொண்ட உப்பங்கழி பொழுதுபோக்கு துறை.','घोषित समय में संचालक द्वारा नौकायन देने वाली बैकवॉटर मनोरंजन जेट्टी.')],
    [L('Covelong coastal path','கோவளம் கடலோர நடைபாதை','कोवलम तटीय पथ'),L('A short shoreline walk planned in the cooler morning or late afternoon.','குளிர்ந்த காலை அல்லது பிற்பகுதியில் திட்டமிடப்படும் குறுகிய கடற்கரை நடை.','ठंडी सुबह या देर दोपहर में रखी गई छोटी तटीय सैर.')]
  ]},
  { id:'SP-LEI-BEACH-SI-001', category:'Beach & Coastal', type:'Beach & Coastal Tours', region:'South India', states:['Kerala'], destination:L('Varkala, Kerala','வர்க்கலா, கேரளா','वर्कला, केरल'), start:'Varkala', end:'Varkala', title:L('Varkala Cliff & Coastal Leisure','வர்க்கலா பாறைமேடு மற்றும் கடலோர ஓய்வு','वर्कला क्लिफ़ और तटीय आराम'), overview:L('A relaxed Kerala coast stay with cliff-top views and a backwater visit. Day one follows the Varkala cliff promenade and Papanasam Beach from the marked access points; day two visits Kappil Lake and the coastal road lookout. Swimming is not included and depends on lifeguard flags and sea conditions.','பாறைமேல் காட்சியும் உப்பங்கழி வருகையும் கொண்ட நிதானமான கேரளக் கடற்கரைப் பயணம். முதல் நாள் குறிக்கப்பட்ட அணுகல் வழியாக வர்க்கலா பாறைமேடு நடைபாதை மற்றும் பாபநாசம் கடற்கரை; இரண்டாம் நாள் கப்பில் ஏரி மற்றும் கடலோரச் சாலை காட்சியிடம். நீச்சல் சேர்க்கப்படவில்லை; உயிர்காப்பாளர் கொடி மற்றும் கடல் நிலையைச் சார்ந்தது.','चट्टान किनारे के दृश्य और बैकवॉटर भ्रमण वाली आरामदायक केरल तटीय यात्रा। पहले दिन चिह्नित रास्ते से वर्कला क्लिफ़ मार्ग और पापनाशम बीच; दूसरे दिन कप्पिल झील और तटीय सड़क दृश्य स्थल। तैराकी शामिल नहीं है और लाइफ़गार्ड संकेत व समुद्र की स्थिति पर निर्भर है।'), best:L('October to March; December to February is generally the driest and most comfortable.','அக்டோபர் முதல் மார்ச் வரை; டிசம்பர் முதல் பிப்ரவரி வரை பொதுவாக வறட்சியும் வசதியும் அதிகம்.','अक्टूबर से मार्च; दिसंबर से फरवरी आम तौर पर सबसे सूखा और आरामदायक समय है.'), weather:L('Typical peak-season daytime 24–31°C and nights 22–25°C; warm, humid coast.','உச்ச பருவத்தில் பகலில் பொதுவாக 24–31°C, இரவில் 22–25°C; வெப்பமான ஈரக் கடற்கரை.','मुख्य मौसम में दिन आम तौर पर 24–31°C और रात 22–25°C; गर्म और नम तटीय मौसम.'), source:'https://www.incredibleindia.gov.in/en/kerala/varkala', sourceName:'Incredible India · Varkala', photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Varkala_Beach.jpg/1280px-Varkala_Beach.jpg', photoCredit:'Varkala Beach · Wikimedia Commons', extra:L('The cliff edge has barriers and restricted areas; stay on the marked path. The beach can have strong currents, and swimming should follow lifeguard advice.','பாறை விளிம்பில் தடுப்புகளும் தடைப்பகுதிகளும் உள்ளன; குறிக்கப்பட்ட பாதையில் செல்லவும். கடற்கரையில் வலுவான நீரோட்டம் இருக்கலாம்; உயிர்காப்பாளர் அறிவுரைப்படி மட்டுமே நீந்தவும்.','क्लिफ़ किनारे पर अवरोध और प्रतिबंधित क्षेत्र हैं; चिह्नित मार्ग पर रहें। समुद्र तट पर तेज़ धाराएँ हो सकती हैं; लाइफ़गार्ड की सलाह से ही तैरें.'), stops:[
    [L('Varkala cliff promenade','வர்க்கலா பாறைமேடு நடைபாதை','वर्कला क्लिफ़ मार्ग'),L('A cliff-top public promenade with sea views, cafés and marked access paths.','கடற்காட்சி, சிற்றுண்டி இடங்கள் மற்றும் குறிக்கப்பட்ட பாதைகள் கொண்ட பொதுப் பாறைமேல் நடைபாதை.','समुद्र दृश्य, कैफ़े और चिह्नित पहुँच मार्ग वाला सार्वजनिक क्लिफ़ किनारा मार्ग.')],
    [L('Papanasam Beach access','பாபநாசம் கடற்கரை அணுகல்','पापनाशम बीच प्रवेश'),L('The main beach below the cliff; conditions and swimming safety vary by tide and surf.','பாறையின் கீழுள்ள முக்கியக் கடற்கரை; அலை மற்றும் கடல் நிலைப்படி நீச்சல் பாதுகாப்பு மாறும்.','क्लिफ़ के नीचे मुख्य समुद्र तट; ज्वार और लहर के अनुसार स्थिति व तैराकी सुरक्षा बदलती है.')],
    [L('Kappil Lake viewpoint','கப்பில் ஏரிக் காட்சியிடம்','कप्पिल झील दृश्य स्थल'),L('A calm backwater-lake lookout near the coast, with a short walk along the shore.','கடற்கரைக்கு அருகிலுள்ள அமைதியான உப்பங்கழி ஏரிக் காட்சியிடம்; கரையோர குறுகிய நடை.','तट के पास शांत बैकवॉटर झील दृश्य स्थल और किनारे की छोटी सैर.')],
    [L('Edava coastal road lookout','எடவா கடலோரச் சாலை காட்சியிடம்','एडवा तटीय सड़क दृश्य स्थल'),L('A roadside ocean-and-lagoon view stop; park only in the designated pull-off.','கடலும் காயலும் காணும் சாலையோர நிறுத்தம்; குறிப்பிட்ட இடத்திலேயே வாகனத்தை நிறுத்தவும்.','समुद्र और लैगून का सड़क किनारे दृश्य पड़ाव; निर्धारित जगह पर ही वाहन रोकें.')]
  ]},
  { id:'SP-LEI-BEACH-SI-002', category:'Beach & Coastal', type:'Beach & Coastal Tours', region:'South India', states:['Karnataka'], destination:L('Gokarna, Karnataka','கோகர்ணா, கர்நாடகா','गोकर्ण, कर्नाटक'), start:'Gokarna', end:'Gokarna', title:L('Gokarna Cove Walks & Beach Days','கோகர்ணா சிறுகுடா நடை மற்றும் கடற்கரை நாட்கள்','गोकर्ण खाड़ी सैर और समुद्र तट दिन'), overview:L('A coastal walking holiday linking Gokarna’s public beaches by short road transfers and marked footpaths. Day one visits Kudle and Om beaches; day two follows the permitted trail toward Half Moon and Paradise beaches, returning by boat only if an operator is running safely. Steep paths and sea conditions require care.','குறுகிய சாலைப் பயணங்களும் குறிக்கப்பட்ட நடைபாதைகளும் வழியாக கோகர்ணாவின் பொதுக் கடற்கரைகளை இணைக்கும் கடலோர நடைப்பயணம். முதல் நாள் குட்லே மற்றும் ஓம் கடற்கரைகள்; இரண்டாம் நாள் அனுமதிக்கப்பட்ட பாதையில் ஹாஃப் மூன் மற்றும் பாரடைஸ் கடற்கரைகள், பாதுகாப்பாக இயக்குநர் சேவை இருந்தால் மட்டுமே படகில் திரும்புதல். செங்குத்தான பாதையும் கடல் நிலையும் கவனிக்கப்பட வேண்டும்.','छोटी सड़क यात्राओं और चिह्नित पैदल पथों से गोकर्ण के सार्वजनिक समुद्र तट जोड़ने वाली तटीय पदयात्रा। पहले दिन कुडले और ओम बीच; दूसरे दिन अनुमत मार्ग से हाफ़ मून और पैराडाइज़ बीच, नाव से वापसी केवल सुरक्षित संचालन होने पर। खड़ी पगडंडियों और समुद्र की स्थिति का ध्यान रखें।'), best:L('November to February; avoid monsoon-season beach trails and boat crossings.','நவம்பர் முதல் பிப்ரவரி வரை; பருவமழைக் கடற்கரைப் பாதை மற்றும் படகுப் பயணத்தைத் தவிர்க்கவும்.','नवंबर से फरवरी; मानसून के समुद्र तट मार्ग और नाव यात्रा से बचें.'), weather:L('Typical peak-season daytime 23–32°C and nights 20–24°C; sunny and humid with sea breezes.','உச்ச பருவத்தில் பகலில் பொதுவாக 23–32°C, இரவில் 20–24°C; வெயிலும் ஈரப்பதமும் கடற்காற்றும்.','मुख्य मौसम में दिन आम तौर पर 23–32°C और रात 20–24°C; धूप, उमस और समुद्री हवा.'), source:'https://www.incredibleindia.gov.in/en/karnataka/gokarna', sourceName:'Incredible India · Gokarna', photo:'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Om_Beach_Gokarna.jpg/1280px-Om_Beach_Gokarna.jpg', photoCredit:'Om Beach · Wikimedia Commons', extra:L('The trail between beaches has steep sections and little shade. Some beaches do not have lifeguards; do not enter the water when flags or local advice prohibit it.','கடற்கரைகளுக்கிடையிலான பாதையில் செங்குத்தான பகுதிகளும் குறைந்த நிழலும் உண்டு. சில கடற்கரைகளில் உயிர்காப்பாளர் இல்லை; கொடி அல்லது உள்ளூர் அறிவுரை தடை செய்தால் கடலில் இறங்க வேண்டாம்.','समुद्र तटों के बीच पगडंडी में खड़ी चढ़ाई और कम छाया है। कुछ तटों पर लाइफ़गार्ड नहीं होते; झंडा या स्थानीय सलाह मना करे तो पानी में न जाएँ.'), stops:[
    [L('Kudle Beach access','குட்லே கடற்கரை அணுகல்','कुडले बीच प्रवेश'),L('A broad curved beach reached by a short downhill walk from the road.','சாலையிலிருந்து குறுகிய இறக்க நடை வழியாகச் செல்லும் வளைந்த அகன்ற கடற்கரை.','सड़क से थोड़ी उतराई वाली पैदल राह से पहुँचा जाने वाला चौड़ा घुमावदार तट.')],
    [L('Om Beach north lookout','ஓம் கடற்கரை வடக்குக் காட்சியிடம்','ओम बीच उत्तरी दृश्य स्थल'),L('A headland view over the curved shoreline; the beach name describes its shape.','வளைந்த கரையை நோக்கும் முனை காட்சியிடம்; கடற்கரையின் பெயர் அதன் வடிவத்தைச் சுட்டுகிறது.','मुड़ी हुई तटरेखा का हेडलैंड दृश्य; समुद्र तट का नाम उसके आकार से जुड़ा है.')],
    [L('Half Moon Beach trail','ஹாஃப் மூன் கடற்கரை நடைபாதை','हाफ़ मून बीच पगडंडी'),L('A smaller cove accessed by a footpath or licensed boat depending on conditions.','சூழ்நிலையைப் பொறுத்து நடைபாதை அல்லது உரிமம் பெற்ற படகில் செல்லும் சிறிய சிறுகுடா.','स्थिति के अनुसार पैदल पथ या लाइसेंस प्राप्त नाव से पहुँची जाने वाली छोटी खाड़ी.')],
    [L('Paradise Beach viewpoint','பாரடைஸ் கடற்கரை காட்சியிடம்','पैराडाइज़ बीच दृश्य स्थल'),L('A remote shoreline viewpoint; access is limited and the group returns before dusk.','தொலைவான கடற்கரை காட்சியிடம்; அணுகல் கட்டுப்பாடுடன், குழு இருட்டுவதற்கு முன் திரும்பும்.','दूरस्थ तट दृश्य स्थल; पहुँच सीमित है और समूह अँधेरा होने से पहले लौटेगा.')]
  ]},

  { id:'SP-LEI-LUX-TN-001', category:'Luxury & Wellness', type:'Luxury & Wellness Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Chennai, Tamil Nadu','சென்னை, தமிழ்நாடு','चेन्नई, तमिलनाडु'), start:'Chennai', end:'Chennai', title:L('Chennai Urban Spa & Garden Retreat','சென்னை நகர ஸ்பா மற்றும் தோட்ட ஓய்வு','चेन्नई शहरी स्पा और उद्यान विश्राम'), overview:L('A city wellness break with a private hotel base, a guided garden visit and an optional appointment at a licensed spa. Day one visits Semmozhi Poonga and a quiet Adyar riverfront walk; day two visits Guindy National Park’s marked public nature area and leaves a long spa or pool rest window. Spa treatment is optional and prepaid only after the provider confirms.','தனியார் ஹோட்டல் மையம், வழிகாட்டியுடன் தோட்ட வருகை மற்றும் உரிமம் பெற்ற ஸ்பாவில் விருப்ப நேரமுன்பதிவு கொண்ட நகர நலவாழ்வு பயணம். முதல் நாள் செம்மொழிப் பூங்கா மற்றும் அமைதியான அடையாறு ஆற்றங்கரை நடை; இரண்டாம் நாள் கிண்டி தேசியப் பூங்காவின் பொதுப் பகுதிக்குச் சென்று நீண்ட ஸ்பா அல்லது நீச்சல் குள ஓய்வு. ஸ்பா சிகிச்சை விருப்பத் தேர்வு; வழங்குநர் உறுதிப்படுத்திய பிறகே முன்பணம்.','निजी होटल आधार, गाइडेड उद्यान भ्रमण और लाइसेंस प्राप्त स्पा में वैकल्पिक अपॉइंटमेंट वाला शहरी वेलनेस अवकाश। पहले दिन सेम्मोझि पूंगा और शांत अडयार नदी किनारे सैर; दूसरे दिन गिंडी राष्ट्रीय उद्यान के चिह्नित सार्वजनिक प्रकृति क्षेत्र और लंबा स्पा या पूल विश्राम। स्पा उपचार वैकल्पिक है और प्रदाता की पुष्टि के बाद ही अग्रिम भुगतान करें।'), best:L('November to February; early mornings are comfortable year-round.','நவம்பர் முதல் பிப்ரவரி வரை; ஆண்டு முழுவதும் அதிகாலை வசதியானது.','नवंबर से फरवरी; पूरे साल सुबह जल्दी घूमना आरामदायक रहता है.'), weather:L('Typical peak-season daytime 22–29°C and nights 20–24°C; warm, humid coast with occasional rain.','உச்ச பருவத்தில் பகலில் பொதுவாக 22–29°C, இரவில் 20–24°C; வெப்பமான ஈரக் கடற்கரை, அவ்வப்போது மழை.','मुख्य मौसम में दिन आम तौर पर 22–29°C और रात 20–24°C; गर्म नम तटीय मौसम, कभी-कभी बारिश.'), source:'https://www.incredibleindia.gov.in/en/tamil-nadu/chennai', sourceName:'Incredible India · Chennai', photo:'https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=1200&q=85', photoCredit:'Representative wellness image · Unsplash', extra:L('Spa appointments are subject to therapist and room availability; disclose allergies or medical conditions directly to the licensed provider. Guindy entry is separately ticketed and may require ID.','ஸ்பா நேரம் சிகிச்சையாளர் மற்றும் அறை கிடைப்பைச் சார்ந்தது; ஒவ்வாமை அல்லது உடல்நல நிலையை உரிமம் பெற்ற வழங்குநரிடம் தெரிவிக்கவும். கிண்டி நுழைவுக்கு தனிச் சீட்டு மற்றும் அடையாள அட்டை தேவைப்படலாம்.','स्पा अपॉइंटमेंट थेरेपिस्ट और कमरे की उपलब्धता पर निर्भर है; एलर्जी या स्वास्थ्य स्थिति लाइसेंस प्राप्त प्रदाता को बताएँ। गिंडी प्रवेश पर अलग टिकट और पहचान पत्र लग सकता है.'), stops:[
    [L('Semmozhi Poonga','செம்மொழிப் பூங்கா','सेम्मोझि पूंगा'),L('A botanical city garden with shaded paths and a quiet morning walking loop.','நிழலான நடைபாதைகள் மற்றும் அமைதியான காலை நடைவட்டம் கொண்ட நகரத் தாவரவியல் பூங்கா.','छायादार रास्तों और शांत सुबह के पैदल चक्कर वाला शहर का वनस्पति उद्यान.')],
    [L('Adyar Eco Park public edge','அடையாறு சூழலியல் பூங்கா பொதுப்பகுதி','अडयार इको पार्क सार्वजनिक किनारा'),L('A managed urban wetland setting; public access follows the site’s booking and entry rules.','நிர்வகிக்கப்பட்ட நகர ஈரநிலப் பகுதி; பொதுமக்கள் அணுகல் தளத்தின் முன்பதிவு மற்றும் நுழைவு விதிகளைப் பின்பற்றும்.','प्रबंधित शहरी आर्द्रभूमि; सार्वजनिक पहुँच स्थल के बुकिंग और प्रवेश नियमों के अनुसार है.')],
    [L('Guindy National Park visitor path','கிண்டி தேசியப் பூங்கா பார்வையாளர் நடைபாதை','गिंडी राष्ट्रीय उद्यान आगंतुक पथ'),L('A marked city-park nature route with a short walking loop and visitor facilities.','குறுகிய நடைவட்டம் மற்றும் பார்வையாளர் வசதிகளுடன் குறிக்கப்பட்ட நகரப் பூங்கா இயற்கைப் பாதை.','छोटे पैदल चक्कर और आगंतुक सुविधाओं वाला चिह्नित शहरी प्रकृति मार्ग.')],
    [L('Chennai licensed hotel spa appointment','சென்னை உரிமம் பெற்ற ஹோட்டல் ஸ்பா நேரம்','चेन्नई लाइसेंस प्राप्त होटल स्पा अपॉइंटमेंट'),L('A pre-arranged wellness session at the confirmed hotel or licensed provider; service menu is chosen separately.','உறுதிசெய்யப்பட்ட ஹோட்டல் அல்லது உரிமம் பெற்ற வழங்குநரிடம் முன்கூட்டியே ஏற்பாடு செய்யப்படும் நலவாழ்வு அமர்வு; சேவைத் தேர்வு தனியாகும்.','पुष्टि किए गए होटल या लाइसेंस प्राप्त प्रदाता में पूर्व-निर्धारित वेलनेस सत्र; सेवा सूची अलग चुनी जाएगी.')]
  ]},
  { id:'SP-LEI-LUX-SI-001', category:'Luxury & Wellness', type:'Luxury & Wellness Tours', region:'South India', states:['Kerala'], destination:L('Poovar, Kerala','பூவார், கேரளா','पूवर, केरल'), start:'Poovar', end:'Poovar', title:L('Poovar Estuary Wellness Hideaway','பூவார் முகத்துவார நலவாழ்வு ஓய்வு','पूवर मुहाना वेलनेस विश्राम'), overview:L('A slow coastal wellness stay at Poovar’s estuary, with a short operator-led boat visit and a long hotel rest period. Day one views the Neyyar estuary and mangrove edge by boat; day two is reserved for the golden-sand shoreline and an optional licensed Ayurveda consultation. Boat and wellness services require separate confirmation.','பூவார் முகத்துவாரத்தில் மெதுவான கடலோர நலவாழ்வு தங்கல்; குறுகிய இயக்குநர் வழிப் படகு பயணமும் நீண்ட ஹோட்டல் ஓய்வும் உள்ளன. முதல் நாள் படகில் நெய்யாறு முகத்துவாரம் மற்றும் சதுப்புநில எல்லை; இரண்டாம் நாள் பொன்னிற மணற்கரை மற்றும் விருப்ப ஆயுர்வேத ஆலோசனை. படகு மற்றும் நலவாழ்வு சேவைகள் தனியாக உறுதிப்படுத்தப்பட வேண்டும்.','पूवर मुहाने पर धीमा तटीय वेलनेस प्रवास, जिसमें संचालक के साथ छोटी नाव यात्रा और होटल में लंबा विश्राम है। पहले दिन नाव से नेय्यर मुहाना और मैंग्रोव किनारा; दूसरे दिन सुनहरी रेत वाला तट और वैकल्पिक लाइसेंस प्राप्त आयुर्वेद परामर्श। नाव और वेलनेस सेवाओं की अलग पुष्टि होगी।'), best:L('October to March; December to February is cooler and usually drier.','அக்டோபர் முதல் மார்ச் வரை; டிசம்பர் முதல் பிப்ரவரி வரை குளிர்ச்சியும் பொதுவாக வறட்சியும்.','अक्टूबर से मार्च; दिसंबर से फरवरी ठंडा और आम तौर पर सूखा रहता है.'), weather:L('Typical peak-season daytime 24–31°C and nights 22–25°C; humid tropical coast.','உச்ச பருவத்தில் பகலில் பொதுவாக 24–31°C, இரவில் 22–25°C; ஈரமான வெப்பமண்டலக் கடற்கரை.','मुख्य मौसम में दिन आम तौर पर 24–31°C और रात 22–25°C; नम उष्णकटिबंधीय तट.'), source:'https://www.keralatourism.org/destination/poovar/56', sourceName:'Kerala Tourism · Poovar', photo:'https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=1200&q=85', photoCredit:'Representative wellness image · Unsplash', extra:L('Boat access depends on tide and weather. Ayurveda treatments should be selected directly with a licensed centre after disclosing medications, pregnancy or health conditions.','படகு அணுகல் அலை மற்றும் வானிலையைச் சார்ந்தது. மருந்துகள், கர்ப்பம் அல்லது உடல்நல நிலையைத் தெரிவித்து உரிமம் பெற்ற மையத்துடன் ஆயுர்வேத சிகிச்சையைத் தேர்ந்தெடுக்கவும்.','नाव की पहुँच ज्वार और मौसम पर निर्भर है। दवाएँ, गर्भावस्था या स्वास्थ्य स्थिति बताकर लाइसेंस प्राप्त केंद्र से आयुर्वेद उपचार चुनें.'), stops:[
    [L('Poovar estuary boat jetty','பூவார் முகத்துவாரப் படகுத் துறை','पूवर मुहाना नाव जेट्टी'),L('A local jetty for guided boat trips through the estuary and mangrove channels.','முகத்துவாரம் மற்றும் சதுப்புநில கால்வாய்களில் வழிகாட்டியுடன் படகு பயணத்திற்கான உள்ளூர் துறை.','मुहाने और मैंग्रोव नहरों में गाइडेड नाव यात्रा के लिए स्थानीय जेट्टी.')],
    [L('Neyyar estuary mangrove channel','நெய்யாறு முகத்துவார சதுப்புநிலக் கால்வாய்','नेय्यर मुहाना मैंग्रोव नहर'),L('A calm channel where brackish water and coastal vegetation meet; remain seated during the boat ride.','உவர்நீரும் கடலோரத் தாவரங்களும் கூடும் அமைதியான கால்வாய்; படகுப் பயணத்தில் அமர்ந்திருக்கவும்.','शांत जलमार्ग जहाँ खारा पानी और तटीय वनस्पति मिलते हैं; नाव यात्रा में बैठे रहें.')],
    [L('Poovar golden-sand shoreline','பூவார் பொன்னிற மணற்கரை','पूवर सुनहरी रेत तट'),L('A narrow coastal sandbar reached by boat; access changes with tide and current.','படகில் செல்லும் குறுகிய மணல் திட்டு; அலை மற்றும் நீரோட்டத்தால் அணுகல் மாறும்.','नाव से पहुँची जाने वाली संकरी तटीय रेत पट्टी; ज्वार और धार से पहुँच बदलती है.')],
    [L('Poovar licensed Ayurveda centre','பூவார் உரிமம் பெற்ற ஆயுர்வேத மையம்','पूवर लाइसेंस प्राप्त आयुर्वेद केंद्र'),L('A wellness consultation or treatment at a licensed centre, scheduled only after direct confirmation.','உரிமம் பெற்ற மையத்தில் நலவாழ்வு ஆலோசனை அல்லது சிகிச்சை; நேரடி உறுதிப்படுத்தலுக்குப் பிறகே திட்டமிடப்படும்.','लाइसेंस प्राप्त केंद्र में वेलनेस परामर्श या उपचार; सीधे पुष्टि के बाद ही समय तय होगा.')]
  ]},
  { id:'SP-LEI-LUX-WI-001', category:'Luxury & Wellness', type:'Luxury & Wellness Tours', region:'West India', states:['Rajasthan'], destination:L('Jaisalmer, Rajasthan','ஜெய்சால்மர், ராஜஸ்தான்','जैसलमेर, राजस्थान'), start:'Jaisalmer', end:'Jaisalmer', title:L('Jaisalmer Desert Camp & Sunset Retreat','ஜெய்சால்மர் பாலைவன முகாம் மற்றும் அஸ்தமன ஓய்வு','जैसलमेर रेगिस्तान कैंप और सूर्यास्त विश्राम'), overview:L('A comfort-led desert stay with a private camp base and carefully timed open-air visits. Day one follows a late-afternoon dune transfer for sunset; day two visits Gadisar Lake and the accessible desert landscape lookout. Camp meals, camel rides and cultural programmes are excluded unless selected in the final quotation.','தனியார் முகாம் தங்குமிடத்தையும் நேரம் பார்த்த திறந்தவெளி வருகைகளையும் கொண்ட வசதியான பாலைவனப் பயணம். முதல் நாள் பிற்பகுதியில் மணற்குன்றுகளுக்குச் சென்று அஸ்தமனக் காட்சி; இரண்டாம் நாள் கடிசர் ஏரி மற்றும் அணுகக்கூடிய பாலைவனக் காட்சியிடம். இறுதி விலைப்பட்டியலில் தேர்வு செய்யாவிட்டால் முகாம் உணவு, ஒட்டகச் சவாரி மற்றும் நிகழ்ச்சி சேராது.','निजी कैंप आधार और समयबद्ध खुले भ्रमण वाला आरामदायक रेगिस्तानी प्रवास। पहले दिन देर दोपहर टीलों तक जाकर सूर्यास्त; दूसरे दिन गड़ीसर झील और सुलभ रेगिस्तानी दृश्य स्थल। अंतिम कोटेशन में चुने बिना कैंप भोजन, ऊँट सवारी और सांस्कृतिक कार्यक्रम शामिल नहीं हैं।'), best:L('October to February; December and January nights are cold.','அக்டோபர் முதல் பிப்ரவரி வரை; டிசம்பர் மற்றும் ஜனவரி இரவுகள் குளிரானவை.','अक्टूबर से फरवरी; दिसंबर और जनवरी की रातें ठंडी होती हैं.'), weather:L('Typical peak-season daytime 20–28°C and nights 5–12°C; dry desert air and large day-night change.','உச்ச பருவத்தில் பகலில் பொதுவாக 20–28°C, இரவில் 5–12°C; வறண்ட பாலைவனக் காற்று மற்றும் பகல்-இரவு வெப்ப வேறுபாடு.','मुख्य मौसम में दिन आम तौर पर 20–28°C और रात 5–12°C; शुष्क रेगिस्तानी हवा और दिन-रात में बड़ा तापांतर.'), source:'https://www.incredibleindia.gov.in/en/rajasthan/jaisalmer', sourceName:'Incredible India · Jaisalmer', photo:'https://images.unsplash.com/photo-1477587458883-47145ed94245?w=1200&q=85', photoCredit:'Representative desert image · Unsplash', extra:L('Choose a camp with written confirmation of tent category, washroom arrangement and heating. Carry a warm layer; camel rides and evening programmes are optional and paid separately.','கூடார வகை, கழிப்பறை வசதி மற்றும் வெப்பமூட்டல் குறித்த எழுத்துப்பூர்வ உறுதிப்படுத்தல் உள்ள முகாமைத் தேர்ந்தெடுக்கவும். வெப்பமான மேலாடை எடுத்துச் செல்லவும்; ஒட்டகச் சவாரி மற்றும் மாலை நிகழ்ச்சிகள் விருப்பத் தேர்வு, தனிக் கட்டணம்.','टेंट श्रेणी, शौचालय व्यवस्था और हीटिंग की लिखित पुष्टि वाला कैंप चुनें। गर्म कपड़े रखें; ऊँट सवारी और शाम के कार्यक्रम वैकल्पिक तथा अलग शुल्क पर हैं.'), stops:[
    [L('Sam Sand Dunes sunset area','சாம் மணற்குன்று அஸ்தமனப் பகுதி','सम सैंड ड्यून्स सूर्यास्त क्षेत्र'),L('A designated dune area for sunset viewing; access follows the camp operator’s permitted route.','முகாம் இயக்குநரின் அனுமதிக்கப்பட்ட பாதையின்படி செல்லும் அஸ்தமனக் காட்சிப் பகுதி.','कैंप संचालक के अनुमत मार्ग से पहुँचा जाने वाला सूर्यास्त देखने का निर्धारित टीला क्षेत्र.')],
    [L('Jaisalmer desert camp arrival point','ஜெய்சால்மர் பாலைவன முகாம் வருகை இடம்','जैसलमेर रेगिस्तानी कैंप आगमन स्थल'),L('A pre-confirmed camp check-in point; tent amenities and meal inclusions vary by supplier.','முன் உறுதிசெய்யப்பட்ட முகாம் செக்-இன் இடம்; கூடார வசதிகளும் உணவு சேர்க்கையும் வழங்குநர்படி மாறும்.','पूर्व-पुष्टि वाला कैंप चेक-इन स्थल; टेंट सुविधाएँ और भोजन शामिल होना आपूर्तिकर्ता के अनुसार बदलता है.')],
    [L('Gadisar Lake promenade','கடிசர் ஏரிக்கரை நடைபாதை','गड़ीसर झील तट मार्ग'),L('A calm reservoir promenade with a short walking loop and open morning light.','குறுகிய நடைவட்டமும் திறந்த காலை ஒளியும் கொண்ட அமைதியான நீர்த்தேக்கக் கரை.','छोटे पैदल चक्कर और सुबह की खुली रोशनी वाला शांत जलाशय किनारा.')],
    [L('Khuri desert landscape lookout','குரி பாலைவனக் காட்சியிடம்','खुरी रेगिस्तानी दृश्य स्थल'),L('A daylight look across the open sand landscape; no off-road driving is included.','திறந்த மணற்பரப்பைக் காணும் பகல் காட்சியிடம்; சாலைக்கு வெளியே வாகனப் பயணம் சேர்க்கப்படவில்லை.','खुले रेतीले परिदृश्य का दिन का दृश्य स्थल; ऑफ-रोड ड्राइव शामिल नहीं है.')]
  ]},

  { id:'SP-LEI-MICE-TN-001', category:'Corporate & MICE', type:'Corporate / MICE Tours', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Coimbatore, Tamil Nadu','கோயம்புத்தூர், தமிழ்நாடு','कोयंबटूर, तमिलनाडु'), start:'Coimbatore Airport or Railway Station', end:'Coimbatore Airport or Railway Station', title:L('Coimbatore Two-Day Meeting & Team Reset','கோயம்புத்தூர் இரண்டு நாள் கூட்டம் மற்றும் குழு ஓய்வு','कोयंबटूर दो-दिवसीय बैठक और टीम विश्राम'), overview:L('A practical business itinerary based in Coimbatore, with a half-day meeting at a proposed conference venue selected after group and equipment requirements are reviewed and a short local nature visit. Day one is reserved for venue check-in, meeting blocks and a working break; day two includes the Tamil Nadu Agricultural University Botanical Garden and a closing team session. Venue, room equipment and catering require separate confirmation.','குழு மற்றும் உபகரணத் தேவைகளைச் சரிபார்த்த பிறகு தேர்ந்தெடுக்கப்படும் மாநாட்டு இடத்தில் அரைநாள் கூட்டமும் குறுகிய உள்ளூர் இயற்கை வருகையும் கொண்ட நடைமுறை வணிகப் பயணம். முதல் நாள் இடம் செக்-இன், கூட்ட அமர்வுகள் மற்றும் பணியிடைவேளை; இரண்டாம் நாள் தமிழ்நாடு வேளாண்மைப் பல்கலைக்கழக தாவரவியல் பூங்கா மற்றும் நிறைவு குழு அமர்வு. இடம், அறை உபகரணம் மற்றும் கேட்டரிங்கிற்கு தனி உறுதிப்படுத்தல் தேவை.','कोयंबटूर में व्यावहारिक व्यावसायिक कार्यक्रम, जिसमें समूह और उपकरण की ज़रूरत जाँचने के बाद चुने जाने वाले संभावित सम्मेलन स्थल पर आधे दिन की बैठक और छोटी स्थानीय प्रकृति यात्रा है। पहले दिन स्थल चेक-इन, बैठक सत्र और कार्य विराम; दूसरे दिन तमिलनाडु कृषि विश्वविद्यालय वनस्पति उद्यान और समापन टीम सत्र। स्थल, कमरे के उपकरण और भोजन अलग से पक्के होंगे।'), best:L('November to February for comfortable outdoor transfers; business events run year-round.','வெளிப்புற இடமாற்றத்திற்கு நவம்பர் முதல் பிப்ரவரி வரை வசதி; வணிக நிகழ்வுகள் ஆண்டு முழுவதும் நடைபெறலாம்.','आरामदायक बाहरी स्थानांतरण के लिए नवंबर से फरवरी; व्यावसायिक कार्यक्रम पूरे साल हो सकते हैं.'), weather:L('Typical peak-season daytime 22–30°C and nights 18–22°C; warm and relatively dry.','உச்ச பருவத்தில் பகலில் பொதுவாக 22–30°C, இரவில் 18–22°C; வெப்பமும் ஒப்பீட்டளவில் வறட்சியும்.','मुख्य मौसम में दिन आम तौर पर 22–30°C और रात 18–22°C; गर्म और अपेक्षाकृत सूखा मौसम.'), source:'https://www.incredibleindia.gov.in/en/tamil-nadu/coimbatore', sourceName:'Incredible India · Coimbatore', photo:'https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=1200&q=85', photoCredit:'Representative conference venue image · Unsplash', extra:L('Conference room, projector, sound system, Wi-Fi, meals and delegate materials are not included unless itemized. Submit attendee count, accessibility needs and equipment checklist before the venue hold.','பட்டியலில் தனியாகச் சேர்க்கப்படாவிட்டால் கூட்ட அறை, புரொஜெக்டர், ஒலி அமைப்பு, Wi-Fi, உணவு மற்றும் பிரதிநிதி பொருட்கள் சேராது. இடத்தைத் தற்காலிகமாகப் பதிவு செய்வதற்கு முன் பங்கேற்பாளர் எண்ணிக்கை, அணுகல் தேவைகள் மற்றும் உபகரணப் பட்டியலை வழங்கவும்.','अलग से सूचीबद्ध न होने पर सम्मेलन कक्ष, प्रोजेक्टर, ध्वनि प्रणाली, Wi-Fi, भोजन और प्रतिभागी सामग्री शामिल नहीं हैं। स्थल होल्ड से पहले प्रतिभागी संख्या, पहुँच ज़रूरत और उपकरण सूची दें.'), stops:[
    [L('Candidate Coimbatore meeting venue','கோயம்புத்தூர் கூட்டத்திற்கான பரிந்துரைக்கப்படும் இடம்','कोयंबटूर बैठक के लिए संभावित स्थल'),L('A hotel or business venue selected for the group after capacity and equipment checks.','குழு அளவு மற்றும் உபகரணச் சரிபார்ப்புக்குப் பிறகு தேர்ந்தெடுக்கப்படும் ஹோட்டல் அல்லது வணிக இடம்.','समूह क्षमता और उपकरण जाँच के बाद चुना गया होटल या व्यावसायिक स्थल.')],
    [L('Meeting room session','கூட்ட அறை அமர்வு','बैठक कक्ष सत्र'),L('A scheduled session block; meeting-room hire and AV services require a separate venue order.','திட்டமிட்ட அமர்வு; கூட்ட அறை வாடகை மற்றும் AV சேவைகளுக்கு தனி இட ஆணை தேவை.','निर्धारित सत्र; बैठक कक्ष किराया और AV सेवाओं के लिए स्थल का अलग ऑर्डर चाहिए.')],
    [L('Tamil Nadu Agricultural University Botanical Garden','தமிழ்நாடு வேளாண்மைப் பல்கலைக்கழக தாவரவியல் பூங்கா','तमिलनाडु कृषि विश्वविद्यालय वनस्पति उद्यान'),L('A university garden with labelled plant collections and an easy walking route.','பெயர்ப் பலகையுடன் தாவரத் தொகுப்புகள் மற்றும் எளிய நடைபாதை கொண்ட பல்கலைக்கழகத் தோட்டம்.','नाम-पट्ट वाले पौध संग्रह और आसान पैदल मार्ग वाला विश्वविद्यालय उद्यान.')],
    [L('Coimbatore team wrap-up venue','கோயம்புத்தூர் குழு நிறைவு இடம்','कोयंबटूर टीम समापन स्थल'),L('A quiet indoor meeting point near the hotel for a final review before departure.','புறப்படும் முன் இறுதி மதிப்பாய்விற்காக ஹோட்டல் அருகிலுள்ள அமைதியான உள்ளரங்கு இடம்.','रवाना होने से पहले अंतिम समीक्षा के लिए होटल के पास शांत इनडोर बैठक स्थल.')]
  ]},
  { id:'SP-LEI-MICE-SI-001', category:'Corporate & MICE', type:'Corporate / MICE Tours', region:'South India', states:['Telangana'], destination:L('Hyderabad, Telangana','ஹைதராபாத், தெலங்கானா','हैदराबाद, तेलंगाना'), start:'Hyderabad Airport or Railway Station', end:'Hyderabad Airport or Railway Station', title:L('Hyderabad Conference & City Green Break','ஹைதராபாத் மாநாடு மற்றும் நகரப் பசுமை ஓய்வு','हैदराबाद सम्मेलन और शहरी हरियाली अवकाश'), overview:L('A focused two-day corporate stay with a half-day meeting and an easy outdoor break. Day one covers arrival, a scheduled session at a proposed convention hotel selected after group requirements are reviewed and a working pause; day two visits Durgam Cheruvu lakefront and Hyderabad Botanical Garden before the departure transfer. Meeting facilities and technical production require separate confirmation.','அரைநாள் கூட்டமும் எளிய வெளிப்புற ஓய்வும் கொண்ட இரண்டு நாள் நிறுவனப் பயணம். முதல் நாள் வருகை, குழுத் தேவைகளைச் சரிபார்த்த பிறகு தேர்ந்தெடுக்கப்படும் மாநாட்டு ஹோட்டலில் அமர்வு மற்றும் பணியிடைவேளை; இரண்டாம் நாள் துர்கம் செருவு ஏரிக்கரை மற்றும் ஹைதராபாத் தாவரவியல் பூங்காவுக்குப் பிறகு புறப்படும் இடமாற்றம். கூட்ட வசதிகள் மற்றும் தொழில்நுட்ப அமைப்பு தனியாக உறுதிசெய்யப்படும்.','आधे दिन की बैठक और आसान बाहरी विराम वाला दो-दिवसीय कॉर्पोरेट प्रवास। पहले दिन आगमन, समूह की ज़रूरतें जाँचने के बाद चुने जाने वाले संभावित सम्मेलन होटल में सत्र और कार्य विराम; दूसरे दिन दुर्गम चेरुवु झील किनारा और हैदराबाद वनस्पति उद्यान के बाद प्रस्थान स्थानांतरण। बैठक सुविधाएँ और तकनीकी व्यवस्था अलग से पक्की होगी।'), best:L('October to February for outdoor visits; conference stays suit year-round dates.','வெளிப்புற வருகைக்கு அக்டோபர் முதல் பிப்ரவரி வரை; மாநாட்டுத் தங்கலுக்கு ஆண்டு முழுவதும் தேதிகள் ஏற்றவை.','बाहरी भ्रमण के लिए अक्टूबर से फरवरी; सम्मेलन प्रवास के लिए पूरे साल तारीखें उपयुक्त हैं.'), weather:L('Typical peak-season daytime 20–29°C and nights 14–20°C; mostly dry and sunny.','உச்ச பருவத்தில் பகலில் பொதுவாக 20–29°C, இரவில் 14–20°C; பெரும்பாலும் வறட்சியும் வெயிலும்.','मुख्य मौसम में दिन आम तौर पर 20–29°C और रात 14–20°C; अधिकतर सूखा और धूप वाला मौसम.'), source:'https://www.incredibleindia.gov.in/en/telangana/hyderabad', sourceName:'Incredible India · Hyderabad', photo:'https://images.unsplash.com/photo-1497366811353-6870744d04b2?w=1200&q=85', photoCredit:'Representative meeting venue image · Unsplash', extra:L('Venue hire, AV equipment, internet bandwidth, registration desk, meals and event staffing require a separate written event order. Outdoor visits may shift around traffic.','இட வாடகை, AV உபகரணம், இணைய வேகம், பதிவு மேசை, உணவு மற்றும் நிகழ்ச்சி பணியாளர்களுக்கு தனி எழுத்துப்பூர்வ ஆணை தேவை. போக்குவரத்துக்கு ஏற்ப வெளிப்புற வருகை நேரம் மாறலாம்.','स्थल किराया, AV उपकरण, इंटरनेट बैंडविड्थ, पंजीकरण डेस्क, भोजन और कार्यक्रम स्टाफ के लिए अलग लिखित इवेंट ऑर्डर चाहिए। यातायात के अनुसार बाहरी भ्रमण बदल सकता है.'), stops:[
    [L('Candidate Hyderabad convention hotel','ஹைதராபாத் மாநாட்டிற்கான பரிந்துரைக்கப்படும் ஹோட்டல்','हैदराबाद सम्मेलन के लिए संभावित होटल'),L('The group venue is selected after confirming room capacity, access and meeting equipment.','அறை கொள்ளளவு, அணுகல் மற்றும் கூட்ட உபகரணங்களை உறுதிசெய்த பிறகு குழு இடம் தேர்ந்தெடுக்கப்படும்.','कक्ष क्षमता, पहुँच और बैठक उपकरण की पुष्टि के बाद समूह स्थल चुना जाएगा.')],
    [L('Conference session and networking room','மாநாட்டு அமர்வு மற்றும் தொடர்பு அறை','सम्मेलन सत्र और नेटवर्किंग कक्ष'),L('A scheduled business block with venue access subject to the final event order.','இறுதி நிகழ்ச்சி ஆணைக்குட்பட்ட இட அணுகலுடன் திட்டமிட்ட வணிக அமர்வு.','अंतिम कार्यक्रम आदेश के अधीन स्थल पहुँच वाला नियोजित व्यावसायिक सत्र.')],
    [L('Durgam Cheruvu lakefront','துர்கம் செருவு ஏரிக்கரை','दुर्गम चेरुवु झील किनारा'),L('A managed urban lakefront with walking paths and designated public areas.','நடைபாதைகள் மற்றும் குறிப்பிட்ட பொதுப் பகுதிகள் கொண்ட நிர்வகிக்கப்பட்ட நகர ஏரிக்கரை.','पैदल मार्ग और निर्धारित सार्वजनिक क्षेत्रों वाला प्रबंधित शहरी झील किनारा.')],
    [L('Hyderabad Botanical Garden','ஹைதராபாத் தாவரவியல் பூங்கா','हैदराबाद वनस्पति उद्यान'),L('A planted public garden with shaded trails for a low-intensity team walk.','குறைந்த உழைப்புள்ள குழு நடைப்பயணத்திற்கான நிழல் பாதைகள் கொண்ட பொதுத் தோட்டம்.','हल्की टीम सैर के लिए छायादार पगडंडियों वाला सार्वजनिक उद्यान.')]
  ]},
  { id:'SP-LEI-MICE-SI-002', category:'Corporate & MICE', type:'Corporate / MICE Tours', region:'South India', states:['Karnataka'], destination:L('Bengaluru, Karnataka','பெங்களூரு, கர்நாடகா','बेंगलुरु, कर्नाटक'), start:'Bengaluru Airport or Railway Station', end:'Bengaluru Airport or Railway Station', title:L('Bengaluru Meeting & Garden City Reset','பெங்களூரு கூட்டம் மற்றும் தோட்ட நகர ஓய்வு','बेंगलुरु बैठक और गार्डन सिटी विश्राम'), overview:L('A business-led short stay with a focused meeting block and a green city walk. Day one is reserved for a proposed conference venue selected after group requirements are reviewed, followed by evening rest; day two follows a morning loop through Lalbagh Botanical Garden and a short team walk at Cubbon Park before transfer to the departure point. Room production and event catering are quoted separately.','குறிப்பிட்ட கூட்ட அமர்வும் பசுமையான நகர நடைப்பயணமும் கொண்ட வணிகப் பயணம். முதல் நாள் குழுத் தேவைகளைச் சரிபார்த்த பிறகு தேர்ந்தெடுக்கப்படும் மாநாட்டு இடத்தில் கூட்டமும் மாலை ஓய்வும்; இரண்டாம் நாள் லால்பாக் தாவரவியல் பூங்காவில் காலை நடை மற்றும் கப்பன் பூங்காவில் குறுகிய குழு நடை, பின்னர் புறப்படும் இடத்திற்குச் செல்லுதல். அறை தொழில்நுட்ப அமைப்பும் நிகழ்ச்சி கேட்டரிங்கும் தனி விலை.','केंद्रित बैठक और हरे-भरे शहर की सैर वाला व्यावसायिक छोटा प्रवास। पहले दिन समूह की ज़रूरतें जाँचने के बाद चुने जाने वाले संभावित सम्मेलन स्थल पर बैठक और शाम का विश्राम; दूसरे दिन सुबह लालबाग वनस्पति उद्यान का चक्कर और कब्बन पार्क में छोटी टीम सैर के बाद प्रस्थान स्थल तक स्थानांतरण। तकनीकी व्यवस्था और कार्यक्रम भोजन अलग कोटेशन पर हैं।'), best:L('October to February; outdoor city walks are pleasant through much of the year.','அக்டோபர் முதல் பிப்ரவரி வரை; ஆண்டின் பல மாதங்களில் நகர நடை இனிமையானது.','अक्टूबर से फरवरी; साल के अधिकतर समय शहर की सैर सुहावनी रहती है.'), weather:L('Typical peak-season daytime 21–28°C and nights 14–19°C; mild, with occasional showers.','உச்ச பருவத்தில் பகலில் பொதுவாக 21–28°C, இரவில் 14–19°C; மிதமான வானிலை, அவ்வப்போது மழை.','मुख्य मौसम में दिन आम तौर पर 21–28°C और रात 14–19°C; हल्का मौसम और कभी-कभी बारिश.'), source:'https://www.incredibleindia.gov.in/en/karnataka/bengaluru', sourceName:'Incredible India · Bengaluru', photo:'https://images.unsplash.com/photo-1497366811353-6870744d04b2?w=1200&q=85', photoCredit:'Representative meeting venue image · Unsplash', extra:L('Bengaluru traffic can materially change road time; allow buffer before sessions and flights. Conference room, projector, microphones, internet and meals require written confirmation.','பெங்களூரு போக்குவரத்து சாலை நேரத்தை குறிப்பிடத்தக்க அளவு மாற்றலாம்; கூட்டம் மற்றும் விமானத்திற்கு முன் கூடுதல் நேரம் விடவும். கூட்ட அறை, புரொஜெக்டர், மைக்ரோஃபோன், இணையம் மற்றும் உணவுக்கு எழுத்துப்பூர்வ உறுதிப்படுத்தல் தேவை.','बेंगलुरु यातायात सड़क समय को काफी बदल सकता है; बैठक और उड़ान से पहले अतिरिक्त समय रखें। सम्मेलन कक्ष, प्रोजेक्टर, माइक्रोफ़ोन, इंटरनेट और भोजन की लिखित पुष्टि लें.'), stops:[
    [L('Candidate Bengaluru conference venue','பெங்களூரு மாநாட்டிற்கான பரிந்துரைக்கப்படும் இடம்','बेंगलुरु सम्मेलन के लिए संभावित स्थल'),L('A business hotel or meeting venue selected after checking capacity and delegate access.','கொள்ளளவு மற்றும் பிரதிநிதி அணுகலைச் சரிபார்த்த பிறகு தேர்ந்தெடுக்கப்படும் வணிக ஹோட்டல் அல்லது கூட்ட இடம்.','क्षमता और प्रतिनिधि पहुँच जाँचकर चुना गया व्यावसायिक होटल या बैठक स्थल.')],
    [L('Meeting room session','கூட்ட அறை அமர்வு','बैठक कक्ष सत्र'),L('A scheduled presentation and discussion block; equipment and staffing follow the confirmed event plan.','உறுதிசெய்யப்பட்ட நிகழ்ச்சி திட்டப்படி உபகரணம் மற்றும் பணியாளர்களுடன் திட்டமிடப்படும் விளக்க-கலந்துரையாடல் அமர்வு.','पुष्ट इवेंट योजना के अनुसार उपकरण और स्टाफ वाला नियोजित प्रस्तुति व चर्चा सत्र.')],
    [L('Lalbagh Botanical Garden','லால்பாக் தாவரவியல் பூங்கா','लालबाग वनस्पति उद्यान'),L('A large botanical garden with broad paths and a glasshouse; check event access restrictions.','அகன்ற பாதைகள் மற்றும் கண்ணாடி மாளிகையுடன் கூடிய பெரிய தாவரவியல் பூங்கா; நிகழ்ச்சி அணுகல் கட்டுப்பாடுகளைச் சரிபார்க்கவும்.','चौड़े मार्ग और ग्लासहाउस वाला बड़ा वनस्पति उद्यान; कार्यक्रम के कारण प्रवेश पाबंदी जाँचें.')],
    [L('Cubbon Park team walk','கப்பன் பூங்கா குழு நடை','कब्बन पार्क टीम सैर'),L('A shaded central-city park loop suited to a short, low-intensity group walk.','குறுகிய, குறைந்த உழைப்புள்ள குழு நடைப்பயணத்திற்கு ஏற்ற நிழலான மைய நகரப் பூங்கா சுற்று.','छोटी, हल्की समूह सैर के लिए उपयुक्त छायादार केंद्रीय शहर पार्क चक्कर.')]
  ]},

  { id:'SP-LEI-BUD-TN-001', category:'Budget Weekend Getaways', type:'Budget Weekend Getaways', region:'Tamil Nadu', states:['Tamil Nadu'], destination:L('Yelagiri, Tamil Nadu','ஏலகிரி, தமிழ்நாடு','येलागिरि, तमिलनाडु'), start:'Yelagiri', end:'Yelagiri', title:L('Yelagiri Lake & Short Hill Trails','ஏலகிரி ஏரி மற்றும் குறுகிய மலை நடைபாதைகள்','येलागिरि झील और छोटी पहाड़ी पगडंडियाँ'), overview:L('A simple, low-cost hill weekend with local drives kept short. Day one visits Punganoor Lake and the Nature Park; day two takes a morning walk toward Swamimalai’s lower trail and stops at Jalagamparai Falls if the seasonal path is open. The route stays within Tamil Nadu and avoids a strenuous summit trek.','குறுகிய உள்ளூர் வாகனப் பயணங்களுடன் அமைந்த எளிய குறைந்த செலவு மலை வார இறுதி. முதல் நாள் புங்கனூர் ஏரி மற்றும் இயற்கைப் பூங்கா; இரண்டாம் நாள் சுவாமிமலை கீழ்ப்பாதையில் காலை நடை மற்றும் பருவப் பாதை திறந்திருந்தால் ஜலகம்பாறை அருவி. பயணம் தமிழ்நாட்டிற்குள் மட்டுமே; கடினமான உச்சிமலை ஏற்றம் இல்லை.','छोटी स्थानीय ड्राइव वाला सरल कम खर्च पहाड़ी सप्ताहांत। पहले दिन पुंगनूर झील और नेचर पार्क; दूसरे दिन सुबह स्वामीमलाई के निचले मार्ग पर सैर और मौसमी रास्ता खुला हो तो जलगमपराई झरना। पूरा मार्ग तमिलनाडु में है और कठिन शिखर ट्रेक नहीं है।'), best:L('October to February; avoid rainy days for the waterfall and hillside path.','அக்டோபர் முதல் பிப்ரவரி வரை; அருவி மற்றும் மலைப்பாதைக்கு மழை நாட்களைத் தவிர்க்கவும்.','अक्टूबर से फरवरी; झरने और पहाड़ी मार्ग के लिए बारिश वाले दिन टालें.'), weather:L('Typical peak-season daytime 15–27°C and nights 10–17°C; mild, cooler after sunset.','உச்ச பருவத்தில் பகலில் பொதுவாக 15–27°C, இரவில் 10–17°C; மிதமான வானிலை, சூரிய அஸ்தமனத்திற்குப் பின் குளிர்.','मुख्य मौसम में दिन आम तौर पर 15–27°C और रात 10–17°C; हल्का मौसम, सूर्यास्त के बाद ठंड.'), source:'https://www.tamilnadutourism.com/attractions/hill-stations/yelagiri.php', sourceName:'Tamil Nadu Tourism · Yelagiri', photo:'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=1200&q=85', photoCredit:'Representative road-trip image · Unsplash', extra:L('Swamimalai has steep sections; use the lower marked trail and turn back if it is wet. Confirm lake boating and falls access locally; entry tickets are excluded.','சுவாமிமலையில் செங்குத்தான பகுதிகள் உள்ளன; கீழ் குறிக்கப்பட்ட பாதையைப் பயன்படுத்தி ஈரமாக இருந்தால் திரும்பவும். ஏரி படகு மற்றும் அருவி அணுகலை உள்ளூரில் உறுதிசெய்யவும்; நுழைவுச் சீட்டுகள் சேராது.','स्वामीमलाई में खड़ी चढ़ाई है; निचले चिह्नित मार्ग से जाएँ और गीला होने पर लौटें। झील नौकायन और झरना पहुँच स्थानीय रूप से पक्की करें; प्रवेश टिकट अलग हैं.'), stops:[
    [L('Punganoor Lake Park','புங்கனூர் ஏரி பூங்கா','पुंगनूर झील पार्क'),L('A small hill lake with a public path and ticketed boating when service is operating.','பொது நடைபாதையும் சேவை இயங்கும் போது சீட்டுடன் படகும் கொண்ட சிறிய மலை ஏரி.','सार्वजनिक पथ और सेवा चालू होने पर टिकट वाली नौकायन सुविधा वाली छोटी पहाड़ी झील.')],
    [L('Yelagiri Nature Park','ஏலகிரி இயற்கைப் பூங்கா','येलागिरि नेचर पार्क'),L('A landscaped local park with a short walking loop and family rest areas.','குறுகிய நடைவட்டமும் குடும்ப ஓய்வு இடங்களும் கொண்ட உள்ளூர் பூங்கா.','छोटे पैदल चक्कर और परिवार विश्राम क्षेत्रों वाला स्थानीय पार्क.')],
    [L('Swamimalai lower trail','சுவாமிமலை கீழ்ப்பாதை','स्वामीमलाई निचला मार्ग'),L('A marked forest-edge approach for a short walk; this package does not include the steep full summit route.','குறுகிய நடைப்பயணத்திற்கான குறிக்கப்பட்ட வன விளிம்புப் பாதை; செங்குத்தான முழு உச்சிப் பாதை இதில் இல்லை.','छोटी सैर के लिए चिह्नित वन किनारा मार्ग; पूरा खड़ा शिखर मार्ग इस पैकेज में नहीं है.')],
    [L('Jalagamparai Falls access point','ஜலகம்பாறை அருவி அணுகல் இடம்','जलगमपराई झरना प्रवेश स्थल'),L('A seasonal falls approach reached by road and a short walk, subject to water flow and access.','நீரோட்டம் மற்றும் அணுகலுக்கு உட்பட்டு சாலை மற்றும் குறுகிய நடை வழியாகச் செல்லும் பருவகால அருவி.','पानी के बहाव और पहुँच पर निर्भर, सड़क और छोटी पैदल राह से पहुँचा जाने वाला मौसमी झरना.')]
  ]},
  { id:'SP-LEI-BUD-SI-001', category:'Budget Weekend Getaways', type:'Budget Weekend Getaways', region:'South India', states:['Karnataka'], destination:L('Dandeli, Karnataka','தண்டேலி, கர்நாடகா','दांदेली, कर्नाटक'), start:'Dandeli', end:'Dandeli', title:L('Dandeli Kali River Budget Adventure','தண்டேலி காளி ஆற்றுக் குறைந்த செலவு சாகசம்','दांदेली काली नदी कम बजट रोमांच'), overview:L('A budget-conscious nature weekend with one optional water activity and a short geology stop. Day one visits the Kali river recreation point and Supa Dam viewpoint; day two visits Syntheri Rocks and the town-side riverside trail. Rafting and kayaking are not included by default and require operator, water-level and safety approval.','ஒரு விருப்ப நீர்ச் செயல்பாடும் குறுகிய பாறை அமைப்பு வருகையும் கொண்ட குறைந்த செலவு இயற்கை வார இறுதி. முதல் நாள் காளி ஆற்றுப் பொழுதுபோக்கு இடம் மற்றும் சுபா அணைக் காட்சியிடம்; இரண்டாம் நாள் சிந்தேரி பாறைகள் மற்றும் நகர அருகிலான ஆற்றங்கரை நடை. ராஃப்டிங், கயாக்கிங் இயல்பாக சேராது; இயக்குநர், நீர்மட்டம் மற்றும் பாதுகாப்பு அனுமதி தேவை.','एक वैकल्पिक जल गतिविधि और छोटी भूगर्भीय सैर वाला कम बजट प्रकृति सप्ताहांत। पहले दिन काली नदी मनोरंजन स्थल और सुपा बाँध दृश्य स्थल; दूसरे दिन सिंथेरी रॉक्स और कस्बे के पास नदी किनारा मार्ग। राफ्टिंग और कयाकिंग सामान्यतः शामिल नहीं हैं; संचालक, जलस्तर और सुरक्षा मंज़ूरी चाहिए।'), best:L('November to April; check river activity schedules after heavy rain.','நவம்பர் முதல் ஏப்ரல் வரை; கனமழைக்குப் பின் ஆற்றுச் செயல்பாட்டு அட்டவணையைச் சரிபார்க்கவும்.','नवंबर से अप्रैल; भारी बारिश के बाद नदी गतिविधियों का समय जाँचें.'), weather:L('Typical peak-season daytime 24–33°C and nights 17–22°C; warm days and humid river air.','உச்ச பருவத்தில் பகலில் பொதுவாக 24–33°C, இரவில் 17–22°C; வெப்பமான பகல் மற்றும் ஈரமான ஆற்றுக் காற்று.','मुख्य मौसम में दिन आम तौर पर 24–33°C और रात 17–22°C; गर्म दिन और नदी किनारे उमस.'), source:'https://karnatakatourism.org/en/destinations/dandeli', sourceName:'Karnataka Tourism · Dandeli', photo:'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=1200&q=85', photoCredit:'Representative waterfall image · Unsplash', extra:L('Supa Dam viewing areas follow local security restrictions. Water sports need a licensed operator, life jacket and current water-level approval; carry quick-dry clothing and secure footwear.','சுபா அணைப் பார்வைப் பகுதிகள் உள்ளூர் பாதுகாப்பு விதிகளைப் பின்பற்றும். நீர்விளையாட்டுக்கு உரிமம் பெற்ற இயக்குநர், உயிர்காப்பு ஜாக்கெட் மற்றும் தற்போதைய நீர்மட்ட அனுமதி தேவை; விரைவில் உலரும் உடை மற்றும் உறுதியான காலணி எடுத்துச் செல்லவும்.','सुपा बाँध दृश्य क्षेत्र स्थानीय सुरक्षा नियम मानते हैं। जल क्रीड़ा के लिए लाइसेंस प्राप्त संचालक, लाइफ़ जैकेट और वर्तमान जलस्तर मंज़ूरी चाहिए; जल्दी सूखने वाले कपड़े और मज़बूत जूते रखें.'), stops:[
    [L('Kali River activity point','காளி ஆற்றுச் செயல்பாட்டு இடம்','काली नदी गतिविधि स्थल'),L('An operator-managed river access point for permitted, supervised water activities.','அனுமதிக்கப்பட்ட கண்காணிப்பு நீர்ச் செயல்பாடுகளுக்கான இயக்குநர் நிர்வகிக்கும் ஆற்றுப் பகுதி.','अनुमत निगरानी वाली जल गतिविधियों के लिए संचालक-प्रबंधित नदी पहुँच स्थल.')],
    [L('Supa Dam public viewpoint','சுபா அணைப் பொதுக் காட்சியிடம்','सुपा बाँध सार्वजनिक दृश्य स्थल'),L('A designated viewpoint over the reservoir; restricted dam infrastructure is not entered.','நீர்த்தேக்கத்தைப் பார்க்கும் குறிப்பிட்ட இடம்; தடைசெய்யப்பட்ட அணை கட்டமைப்பிற்குள் செல்ல முடியாது.','जलाशय का निर्धारित दृश्य स्थल; प्रतिबंधित बाँध ढाँचे में प्रवेश नहीं है.')],
    [L('Syntheri Rocks','சிந்தேரி பாறைகள்','सिंथेरी रॉक्स'),L('A tall volcanic rock formation beside the Kaneri River, approached by steps from the road.','சாலையிலிருந்து படிகள் வழியாகச் செல்லும் கனேரி ஆற்றருகிலுள்ள உயரமான எரிமலைப் பாறை அமைப்பு.','सड़क से सीढ़ियों द्वारा पहुँची जाने वाली कनेरी नदी के पास ऊँची ज्वालामुखीय चट्टान संरचना.')],
    [L('Dandeli riverside trail','தண்டேலி ஆற்றங்கரை நடைபாதை','दांदेली नदी किनारा पगडंडी'),L('A short public riverside walk near town; stay on the marked bank path.','நகரத்திற்கு அருகிலுள்ள குறுகிய பொதுக் கரை நடை; குறிக்கப்பட்ட பாதையில் செல்லவும்.','कस्बे के पास छोटी सार्वजनिक नदी किनारा सैर; चिह्नित पथ पर रहें.')]
  ]},
  { id:'SP-LEI-BUD-WI-001', category:'Budget Weekend Getaways', type:'Budget Weekend Getaways', region:'West India', states:['Maharashtra'], destination:L('Nashik, Maharashtra','நாசிக், மகாராஷ்டிரா','नाशिक, महाराष्ट्र'), start:'Nashik', end:'Nashik', title:L('Nashik Vineyard & Waterfall Weekend','நாசிக் திராட்சைத் தோட்டம் மற்றும் அருவி வார இறுதி','नाशिक अंगूर बाग़ और झरना सप्ताहांत'), overview:L('A value-minded Nashik weekend with a vineyard visit and a short nature stop. Day one visits a participating vineyard for a self-guided grounds walk; tasting is optional and paid directly. Day two visits Someshwar Waterfall and the Gangapur Dam public viewpoint. The plan avoids temple stops and keeps the route within Maharashtra.','திராட்சைத் தோட்ட வருகையும் குறுகிய இயற்கை நிறுத்தமும் கொண்ட செலவுச்சிக்கன நாசிக் வார இறுதி. முதல் நாள் பங்கேற்கும் திராட்சைத் தோட்டத்தில் சுயவழிகாட்டி நடை; ருசிப்பது விருப்பத் தேர்வு, நேரடிக் கட்டணம். இரண்டாம் நாள் சோமேஷ்வர் அருவி மற்றும் கங்காபூர் அணைப் பொதுக் காட்சியிடம். கோயில் நிறுத்தங்கள் இல்லை; பயணம் மகாராஷ்டிராவிற்குள்.','बागान भ्रमण और छोटा प्रकृति पड़ाव वाला किफ़ायती नाशिक सप्ताहांत। पहले दिन सहभागी अंगूर बाग़ में स्वयं-निर्देशित सैर; चखना वैकल्पिक और सीधे भुगतान पर। दूसरे दिन सोमेश्वर झरना और गंगापुर बाँध का सार्वजनिक दृश्य स्थल। मंदिर पड़ाव नहीं हैं और पूरा मार्ग महाराष्ट्र में है।'), best:L('November to February; October and March are warmer but still suitable for outdoor visits.','நவம்பர் முதல் பிப்ரவரி வரை; அக்டோபர் மற்றும் மார்ச் வெப்பமானவை, வெளிப்புற வருகைக்கு ஏற்றவை.','नवंबर से फरवरी; अक्टूबर और मार्च गर्म हैं लेकिन खुले भ्रमण के लिए ठीक हैं.'), weather:L('Typical peak-season daytime 22–30°C and nights 10–17°C; dry, sunny days and cool evenings.','உச்ச பருவத்தில் பகலில் பொதுவாக 22–30°C, இரவில் 10–17°C; வறண்ட வெயில் பகலும் குளிர்ந்த மாலையும்.','मुख्य मौसम में दिन आम तौर पर 22–30°C और रात 10–17°C; सूखे धूप वाले दिन और ठंडी शामें.'), source:'https://maharashtratourism.gov.in/districts/nashik/', sourceName:'Maharashtra Tourism · Nashik', photo:'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=1200&q=85', photoCredit:'Representative vineyard image · Unsplash', extra:L('Vineyard entry, tasting, age checks and transport within the property vary by operator. Do not consume alcohol before the scheduled drive; tastings are excluded unless quoted.','திராட்சைத் தோட்ட நுழைவு, ருசிப்பு, வயது சரிபார்ப்பு மற்றும் தோட்டத்திற்குள் போக்குவரத்து இயக்குநர்படி மாறும். திட்டமிட்ட வாகனப் பயணத்திற்கு முன் மதுபானம் அருந்த வேண்டாம்; விலைப்பட்டியலில் சேர்க்காவிட்டால் ருசிப்பு சேராது.','अंगूर बाग़ प्रवेश, चखना, आयु जाँच और परिसर के भीतर परिवहन संचालक के अनुसार बदलते हैं। तय ड्राइव से पहले शराब न लें; कोटेशन में शामिल न हो तो चखना अलग है.'), stops:[
    [L('Gangapur Road vineyard estate','கங்காபூர் சாலை திராட்சைத் தோட்டம்','गंगापुर रोड अंगूर बाग़'),L('A participating vineyard with planted rows and visitor grounds; confirm public access in advance.','வரிசையாகப் பயிரிடப்பட்ட செடிகளும் பார்வையாளர் பகுதியும் கொண்ட பங்கேற்கும் தோட்டம்; முன்கூட்டியே அணுகலை உறுதிசெய்யவும்.','लताओं की कतारों और आगंतुक क्षेत्र वाला सहभागी बाग़; सार्वजनिक पहुँच पहले पक्की करें.')],
    [L('Nashik vineyard tasting room','நாசிக் திராட்சைத் தோட்ட ருசிப்பு அறை','नाशिक अंगूर बाग़ चखना कक्ष'),L('Optional adult-only tasting by reservation; tasting fee and transport are paid separately.','முன்பதிவுடன் பெரியவர்களுக்கு மட்டும் விருப்ப ருசிப்பு; கட்டணமும் போக்குவரத்தும் தனியாகச் செலுத்தப்படும்.','आरक्षण पर वयस्कों के लिए वैकल्पिक चखना; शुल्क और परिवहन अलग से देना होगा.')],
    [L('Someshwar Waterfall','சோமேஷ்வர் அருவி','सोमेश्वर झरना'),L('A seasonal urban-edge waterfall where safe access depends on recent rainfall and local barriers.','சமீப மழை மற்றும் உள்ளூர் தடுப்புகளைப் பொறுத்த பாதுகாப்பான அணுகலுடன் நகர விளிம்பிலுள்ள பருவகால அருவி.','हाल की बारिश और स्थानीय अवरोधों पर निर्भर सुरक्षित पहुँच वाला शहर किनारे का मौसमी झरना.')],
    [L('Gangapur Dam public viewpoint','கங்காபூர் அணைப் பொதுக் காட்சியிடம்','गंगापुर बाँध सार्वजनिक दृश्य स्थल'),L('A public road-side view of the reservoir and surrounding vineyards.','நீர்த்தேக்கமும் சுற்றியுள்ள திராட்சைத் தோட்டங்களும் தெரியும் பொதுச் சாலையோரக் காட்சியிடம்.','जलाशय और आसपास के अंगूर बाग़ों का सार्वजनिक सड़क किनारे दृश्य स्थल.')]
  ]}
];

const routeSignature = pkg => crypto.createHash('sha256').update(JSON.stringify([
  pkg.startingCity.toLowerCase(), pkg.endingCity.toLowerCase(), pkg.locationTags,
  pkg.durationDays, pkg.catalogCategories
])).digest('hex');

const packages = plans.map(plan => {
  const translations = {};
  for (const lang of ['en', 'ta', 'hi']) {
    const c = common[lang];
    const localizedPlace = place => lang === 'en' ? place
      : `${plan.destination[lang].split(',')[0]}${/Airport or Railway Station/i.test(place) ? (lang === 'ta' ? ' விமான நிலையம் அல்லது ரயில் நிலையம்' : ' हवाई अड्डा या रेलवे स्टेशन') : /Jetty/i.test(place) ? (lang === 'ta' ? ' படகுத் துறை' : ' जेट्टी') : ''}`;
    const stop = (index, time) => {
      const [name, brief] = plan.stops[index];
      const context = placeContext[name.en] || {};
      const fallbackImage = index === 0 ? (plan.photo || context.imageUrl || '') : '';
      return {
        time, kind: 'visit', title: name[lang], place: name[lang], description: brief[lang],
        sourceUrl: plan.source, imageUrl: context.imageUrl || fallbackImage,
        imageCredit: context.imageCredit || plan.photoCredit || '',
        imageCreditUrl: context.imageCreditUrl || (plan.photo?.includes('wikimedia.org') ? 'https://commons.wikimedia.org/' : 'https://unsplash.com/license'),
        visitingInfo: lang === 'en'
          ? 'Use the marked public access and follow the venue’s posted hours and safety instructions.'
          : lang === 'ta'
            ? 'குறிக்கப்பட்ட பொதுப் பாதையைப் பயன்படுத்தி, இடத்தின் அறிவிக்கப்பட்ட நேரம் மற்றும் பாதுகாப்பு வழிமுறைகளைப் பின்பற்றவும்.'
            : 'चिह्नित सार्वजनिक रास्ते का उपयोग करें और स्थल के घोषित समय व सुरक्षा निर्देशों का पालन करें.'
      };
    };
    const attractionWord = lang === 'en' ? 'local highlights' : lang === 'ta' ? 'உள்ளூர் சிறப்பிடங்கள்' : 'स्थानीय दर्शनीय स्थल';
    const dayTwo = lang === 'en' ? 'Morning visit and relaxed departure' : lang === 'ta' ? 'காலை வருகை மற்றும் நிதானமான புறப்பாடு' : 'सुबह का भ्रमण और आराम से प्रस्थान';
    const stay = c.stay;
    translations[lang] = {
      title: plan.title[lang], destination: plan.destination[lang],
      startingCity: localizedPlace(plan.start),
      endingCity: localizedPlace(plan.end),
      overview: `${plan.overview[lang]} ${c.about}`,
      tourType: categoryLabels[plan.category][lang], catalogCategory: categoryLabels[plan.category][lang],
      bestTimeToVisit: plan.best[lang], expectedWeather: plan.weather[lang], vehiclePlan: c.vehicle,
      importantBookingInfo: [plan.extra[lang], ...c.booking],
      termsAndConditions: c.terms,
      cancellationPolicy: c.cancellation,
      mealPlan: lang === 'en'
        ? 'Daily Breakfast Included — breakfast only; one hotel breakfast on Day 2 of this 2-day / 1-night route.'
        : lang === 'ta'
          ? 'தினசரி காலை உணவு சேர்க்கப்பட்டுள்ளது — காலை உணவு மட்டும்; இந்த 2 நாள் / 1 இரவு பயணத்தில் 2ஆம் நாள் ஒரு ஹோட்டல் காலை உணவு.'
          : 'दैनिक नाश्ता शामिल — केवल नाश्ता; इस 2 दिन / 1 रात यात्रा के दूसरे दिन होटल का एक नाश्ता।',
      inclusions: c.inclusions, exclusions: c.exclusions,
      itinerary: [
        {
          day: 1, title: `${lang === 'en' ? 'Day 1 · Arrival and' : lang === 'ta' ? 'நாள் 1 · வருகை மற்றும்' : 'दिन 1 · आगमन और'} ${attractionWord}`,
          activities: plan.overview[lang], hotel: stay,
          mealPlan: lang === 'en' ? 'Lunch and dinner are at the traveller’s own expense; no meals are included on Day 1.' : lang === 'ta' ? 'மதிய மற்றும் இரவு உணவு பயணியுடைய செலவு; முதல் நாளில் உணவு சேர்க்கப்படவில்லை.' : 'दोपहर और रात का भोजन यात्री स्वयं देंगे; पहले दिन भोजन शामिल नहीं है.',
          transport: c.vehicle,
          schedule: [
            { time:'09:00', kind:'start', title:lang === 'en' ? `Meet at ${localizedPlace(plan.start)}` : lang === 'ta' ? `${localizedPlace(plan.start)} இடத்தில் சந்திப்பு` : `${localizedPlace(plan.start)} पर मिलें`, place:localizedPlace(plan.start), description:lang === 'en' ? 'Meet the driver, load luggage and begin the local route.' : lang === 'ta' ? 'ஓட்டுநரைச் சந்தித்து, சுமைகளை ஏற்றி உள்ளூர் பயணத்தைத் தொடங்கவும்.' : 'चालक से मिलें, सामान रखें और स्थानीय यात्रा शुरू करें.' },
            stop(0, '09:30'),
            { time:'11:30', kind:'transfer', title:lang === 'en' ? 'Local transfer and rest stop' : lang === 'ta' ? 'உள்ளூர் இடமாற்றம் மற்றும் ஓய்வு' : 'स्थानीय स्थानांतरण और विश्राम', place:plan.destination[lang], description:c.transfer },
            { time:'12:30', kind:'meal', title:lang === 'en' ? 'Lunch break' : lang === 'ta' ? 'மதிய உணவு இடைவேளை' : 'दोपहर भोजन विराम', description:c.lunch },
            stop(1, '14:00'),
            { time:'16:30', kind:'rest', title:lang === 'en' ? 'Hotel check-in and rest' : lang === 'ta' ? 'ஹோட்டல் செக்-இன் மற்றும் ஓய்வு' : 'होटल चेक-इन और विश्राम', place:plan.destination[lang], description:lang === 'en' ? 'Check in when the room is released; the property’s stated check-in time applies.' : lang === 'ta' ? 'அறை கிடைக்கும் போது செக்-இன் செய்யவும்; ஹோட்டல் அறிவித்த நேரம் பொருந்தும்.' : 'कमरा उपलब्ध होने पर चेक-इन करें; होटल का घोषित समय लागू होगा.' },
            { time:'19:00', kind:'end', title:lang === 'en' ? 'Day ends at the hotel' : lang === 'ta' ? 'ஹோட்டலில் நாள் நிறைவு' : 'होटल में दिन का समापन', description:c.dinner }
          ]
        },
        {
          day: 2, title: dayTwo, activities: plan.overview[lang], hotel: lang === 'en' ? 'Check out by 11:00; baggage remains in the vehicle during final visits.' : lang === 'ta' ? '11:00 மணிக்குள் செக்-அவுட்; இறுதி வருகைகளின் போது சுமைகள் வாகனத்தில் இருக்கும்.' : '11:00 बजे तक चेकआउट; अंतिम भ्रमण के दौरान सामान वाहन में रहेगा.',
          mealPlan: c.breakfast, transport: c.vehicle,
          schedule: [
            { time:'07:30', kind:'meal', title:lang === 'en' ? 'Hotel breakfast' : lang === 'ta' ? 'ஹோட்டல் காலை உணவு' : 'होटल नाश्ता', description:c.breakfast },
            stop(2, '09:00'),
            { time:'10:30', kind:'transfer', title:lang === 'en' ? 'Local transfer' : lang === 'ta' ? 'உள்ளூர் இடமாற்றம்' : 'स्थानीय स्थानांतरण', place:plan.destination[lang], description:c.transfer },
            stop(3, '11:00'),
            { time:'13:00', kind:'meal', title:lang === 'en' ? 'Lunch break' : lang === 'ta' ? 'மதிய உணவு இடைவேளை' : 'दोपहर भोजन विराम', description:c.lunch },
            { time:'14:00', kind:'transfer', title:lang === 'en' ? 'Check out and return transfer' : lang === 'ta' ? 'செக்-அவுட் மற்றும் திரும்பும் பயணம்' : 'चेकआउट और वापसी स्थानांतरण', place:localizedPlace(plan.end), description:c.checkout },
            { time:'16:30', kind:'end', title:lang === 'en' ? `Arrive at ${localizedPlace(plan.end)}` : lang === 'ta' ? `${localizedPlace(plan.end)} இடம் வருகை` : `${localizedPlace(plan.end)} पर पहुँचें`, place:localizedPlace(plan.end), description:lang === 'en' ? 'End of the planned itinerary.' : lang === 'ta' ? 'திட்டமிட்ட பயணம் நிறைவு.' : 'योजनाबद्ध यात्रा समाप्त.' }
          ]
        }
      ]
    };
  }
  const pkg = {
    packageId: plan.id, title: plan.title.en, destination: plan.destination.en,
    packageCategory: 'Domestic', tourType: plan.type, catalogCategories: [plan.category],
    regionScope: plan.region, destinationStates: plan.states,
    locationTags: [plan.destination.en, ...plan.stops.map(([name]) => name.en)].map(value => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')),
    hotelCategories: ['3 Star', '4 Star', '5 Star'], startingCity: plan.start, endingCity: plan.end,
    durationDays: 2, durationNights: 1, overview: translations.en.overview,
    bestTimeToVisit: plan.best.en, expectedWeather: plan.weather.en,
    vehiclePlan: common.en.vehicle, importantBookingInfo: translations.en.importantBookingInfo,
    imageUrl: plan.photo, imageRightsNote: plan.photoCredit,
    mealPlan: translations.en.mealPlan,
    itinerary: translations.en.itinerary, inclusions: common.en.inclusions, exclusions: common.en.exclusions,
    optionalAddons: [], templesList: [], destinationReferences: plan.stops.map(([name]) => ({
      name: name.en, url: plan.source, sourceType: 'Tourism board', lastChecked: checkedAt
    })),
    journeyTimeNotes: 'Times are local itinerary windows; short town transfers are allowed 30–60 minutes, with extra buffer for traffic and access queues.',
    journeyDistanceNotes: 'Local route grouped around the listed destination; final road distance depends on the confirmed hotel and venue access.',
    accessibilityNotes: 'Review the stated steps, terrain, activity fitness guidance and mobility needs before requesting confirmation.',
    seasonConstraints: `${plan.best.en} Typical weather: ${plan.weather.en}`,
    termsAndConditions: 'This is a planned itinerary, not a reservation. Hotel, venue, transport and activities are confirmed in writing after date and supplier checks.',
    cancellationPolicy: 'Supplier-specific cancellation and refund terms are provided with the final confirmed quotation before payment.',
    contentReviewedBy: 'SreePayanam catalogue review', contentReviewedAt: checkedAt,
    uniquenessReviewedBy: 'SreePayanam route review', uniquenessReviewedAt: checkedAt,
    status: 'Approved', isActive: true, showInMenu: false, curatedLeisure: true, translations
  };
  pkg.routeSignature = routeSignature(pkg);
  return pkg;
});

const byId = new Map(packages.map(pkg => [pkg.packageId, pkg]));
module.exports = { packages, byId, categoryLabels };
